/**
 * Behavioral tests for {@link IndexImage}.
 * <p>
 * The tests exercise the adaptive palette generation and the indexed image
 * conversion through the public entry points of the class.
 * </p>
 */
@DisplayName("IndexImage")
class IndexImageTests {

    private static final int RED = 0xFFFF0000;
    private static final int GREEN = 0xFF00FF00;
    private static final int BLUE = 0xFF0000FF;
    private static final int WHITE = 0xFFFFFFFF;
    private static final int BLACK = 0xFF000000;

    private static final int TRANSPARENT_RED = 0x00FF0000;

    /**
     * Creates a new {@code TYPE_INT_RGB} image where the colors are painted in diagonal stripes.
     */
    private static BufferedImage stripedImage(int width, int height, int... rgb) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                image.setRGB(x, y, rgb[(x + y) % rgb.length]);
            }
        }

        return image;
    }

    /**
     * Creates a new {@code TYPE_INT_RGB} image containing a smooth (many colors) gradient.
     */
    private static BufferedImage gradientImage(int width, int height) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int r = (x * 255) / (width - 1);
                int g = (y * 255) / (height - 1);
                int b = ((x + y) * 255) / (width + height - 2);
                image.setRGB(x, y, (r << 16) | (g << 8) | b);
            }
        }

        return image;
    }

    /**
     * Creates an 8 bit {@code IndexColorModel} (palette) from the given opaque RGB values.
     */
    private static IndexColorModel palette(int... rgb) {
        byte[] r = new byte[rgb.length];
        byte[] g = new byte[rgb.length];
        byte[] b = new byte[rgb.length];

        for (int i = 0; i < rgb.length; i++) {
            r[i] = (byte) ((rgb[i] >> 16) & 0xFF);
            g[i] = (byte) ((rgb[i] >> 8) & 0xFF);
            b[i] = (byte) (rgb[i] & 0xFF);
        }

        return new IndexColorModel(8, rgb.length, r, g, b);
    }

    /**
     * Creates a {@code TYPE_BYTE_INDEXED} image using all the colors of the given palette.
     */
    private static BufferedImage indexedImage(int width, int height, IndexColorModel colors) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_BYTE_INDEXED, colors);

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                image.getRaster().setSample(x, y, 0, (x + y) % colors.getMapSize());
            }
        }

        return image;
    }

    /**
     * Returns the ARGB color of every pixel in the given image.
     */
    private static Set<Integer> pixels(BufferedImage image) {
        Set<Integer> result = new LinkedHashSet<>();

        for (int y = 0; y < image.getHeight(); y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                result.add(image.getRGB(x, y));
            }
        }

        return result;
    }

    /**
     * Returns the colors (including alpha) contained in the given color model.
     */
    private static Set<Integer> colors(IndexColorModel colorModel) {
        Set<Integer> result = new LinkedHashSet<>();

        for (int i = 0; i < colorModel.getMapSize(); i++) {
            result.add(colorModel.getRGB(i));
        }

        return result;
    }

    /**
     * Counts the number of pixel positions where the two images differ.
     */
    private static int countDifferences(BufferedImage first, BufferedImage second) {
        assertEquals(first.getWidth(), second.getWidth());
        assertEquals(first.getHeight(), second.getHeight());

        int count = 0;

        for (int y = 0; y < first.getHeight(); y++) {
            for (int x = 0; x < first.getWidth(); x++) {
                if (first.getRGB(x, y) != second.getRGB(x, y)) {
                    count++;
                }
            }
        }

        return count;
    }

    private static IndexColorModel colorModel(BufferedImage image) {
        assertTrue(image.getColorModel() instanceof IndexColorModel, "Not an indexed image: " + image);
        return (IndexColorModel) image.getColorModel();
    }

    private static void assertPixelsPreserved(BufferedImage expected, BufferedImage actual) {
        assertEquals(expected.getWidth(), actual.getWidth());
        assertEquals(expected.getHeight(), actual.getHeight());

        for (int y = 0; y < expected.getHeight(); y++) {
            for (int x = 0; x < expected.getWidth(); x++) {
                assertEquals(expected.getRGB(x, y), actual.getRGB(x, y), "Pixel (" + x + ", " + y + ") differs");
            }
        }
    }

    private static void assertOnlyPaletteColors(BufferedImage image) {
        Set<Integer> paletteColors = colors(colorModel(image));
        Set<Integer> imageColors = pixels(image);

        for (Integer color : imageColors) {
            assertTrue(paletteColors.contains(color),
                    "Pixel color " + Integer.toHexString(color) + " not in palette " + paletteColors);
        }
    }

    @Nested
    @DisplayName("hints")
    class Hints {

        @Test
        @DisplayName("isTransparent() should be false for hints that do not involve transparency")
        void isTransparentIsFalseWithoutTransparencyHints() {
            int[] hints = {
                    IndexImage.DITHER_DEFAULT,
                    IndexImage.DITHER_NONE,
                    IndexImage.DITHER_DIFFUSION,
                    IndexImage.DITHER_DIFFUSION_ALTSCANS,
                    IndexImage.COLOR_SELECTION_DEFAULT,
                    IndexImage.COLOR_SELECTION_FAST,
                    IndexImage.COLOR_SELECTION_QUALITY,
                    IndexImage.DITHER_DIFFUSION | IndexImage.COLOR_SELECTION_QUALITY,
                    IndexImage.DITHER_NONE | IndexImage.COLOR_SELECTION_FAST
            };

            for (int hint : hints) {
                assertFalse(IndexImage.isTransparent(hint), "hints: 0x" + Integer.toHexString(hint));
            }
        }

        @Test
        @DisplayName("isTransparent() should be true for the bitmask transparency hint")
        void isTransparentWithBitmaskHint() {
            assertTrue(IndexImage.isTransparent(IndexImage.TRANSPARENCY_BITMASK));
        }

        @Test
        @DisplayName("isTransparent() should be true for the translucent transparency hint")
        void isTransparentWithTranslucentHint() {
            assertTrue(IndexImage.isTransparent(IndexImage.TRANSPARENCY_DEFAULT | IndexImage.TRANSPARENCY_TRANSLUCENT));
        }

        @Test
        @DisplayName("isTransparent() should combine with dither and color selection hints")
        void isTransparentCombinesWithOtherHints() {
            assertTrue(IndexImage.isTransparent(IndexImage.TRANSPARENCY_BITMASK | IndexImage.DITHER_DIFFUSION));
            assertTrue(IndexImage.isTransparent(IndexImage.TRANSPARENCY_BITMASK | IndexImage.COLOR_SELECTION_FAST));
            assertTrue(IndexImage.isTransparent(IndexImage.DITHER_DIFFUSION_ALTSCANS | IndexImage.COLOR_SELECTION_QUALITY
                    | IndexImage.TRANSPARENCY_BITMASK));
        }

        @Test
        @DisplayName("Dither and color selection hint constants should not overlap the transparency bits")
        void hintConstantsLiveInTheirOwnBitRanges() {
            assertEquals(0xFF, IndexImage.DITHER_MASK);
            assertEquals(0xFF00, IndexImage.COLOR_SELECTION_MASK);
            assertEquals(0xFF0000, IndexImage.TRANSPARENCY_MASK);

            assertEquals(0, IndexImage.DITHER_NONE & ~IndexImage.DITHER_MASK);
            assertEquals(0, IndexImage.COLOR_SELECTION_QUALITY & ~IndexImage.COLOR_SELECTION_MASK);
            assertEquals(0, IndexImage.TRANSPARENCY_OPAQUE & ~IndexImage.TRANSPARENCY_MASK);
            assertFalse(IndexImage.isTransparent(IndexImage.DITHER_NONE | IndexImage.COLOR_SELECTION_QUALITY));
        }
    }

    @Nested
    @DisplayName("getIndexColorModel(Image, int, int)")
    class GetIndexColorModel {

        @Test
        @DisplayName("Should create a single color palette for a uniform image")
        void uniformImageGivesSingleColorPalette() {
            BufferedImage image = stripedImage(16, 16, 0xFF123456);

            IndexColorModel colorModel = IndexImage.getIndexColorModel(image, 256, IndexImage.DITHER_DEFAULT);

            assertEquals(1, colorModel.getMapSize());
            assertEquals(0xFF123456, colorModel.getRGB(0));
            assertEquals(Transparency.OPAQUE, colorModel.getTransparency());
        }

        @Test
        @DisplayName("Should contain all distinct colors of the image")
        void containsAllDistinctColors() {
            BufferedImage image = stripedImage(16, 16, RED, GREEN, BLUE, WHITE);

            IndexColorModel colorModel = IndexImage.getIndexColorModel(image, 16, IndexImage.COLOR_SELECTION_QUALITY);

            assertEquals(4, colorModel.getMapSize());
            assertEquals(new LinkedHashSet<>(Arrays.asList(RED, GREEN, BLUE, WHITE)), colors(colorModel));
            assertEquals(Transparency.OPAQUE, colorModel.getTransparency());
        }

        @Test
        @DisplayName("Should never contain more colors than requested")
        void paletteIsLimitedToRequestedNumberOfColors() {
            BufferedImage image = stripedImage(16, 16, RED, GREEN, BLUE, WHITE);

            assertEquals(4, IndexImage.getIndexColorModel(image, 4, IndexImage.DITHER_NONE).getMapSize());
            assertEquals(3, IndexImage.getIndexColorModel(image, 3, IndexImage.DITHER_NONE).getMapSize());
            assertEquals(2, IndexImage.getIndexColorModel(image, 2, IndexImage.DITHER_NONE).getMapSize());
            assertEquals(1, IndexImage.getIndexColorModel(image, 1, IndexImage.DITHER_NONE).getMapSize());
        }

        @Test
        @DisplayName("Should merge image colors when fewer colors than present are requested")
        void mergesColorsWhenFewerColorsAreRequested() {
            BufferedImage image = stripedImage(16, 16, RED, GREEN, BLUE, WHITE);

            IndexColorModel colorModel = IndexImage.getIndexColorModel(image, 2, IndexImage.DITHER_NONE);

            assertEquals(2, colorModel.getMapSize());
            assertEquals(2, colors(colorModel).size());
        }

        @Test
        @DisplayName("Should reuse the palette of an indexed image that has few enough colors")
        void reusesSmallIndexColorModel() {
            IndexColorModel original = palette(RED, GREEN, BLUE);
            BufferedImage image = indexedImage(16, 16, original);

            IndexColorModel colorModel = IndexImage.getIndexColorModel(image, 16, IndexImage.DITHER_NONE);

            assertEquals(original.getMapSize(), colorModel.getMapSize());
            assertEquals(colors(original), colors(colorModel));
        }

        @Test
        @DisplayName("Should recreate the palette of an indexed image that has too many colors")
        void recreatesLargeIndexColorModel() {
            IndexColorModel original = palette(RED, GREEN, BLUE, WHITE);
            BufferedImage image = indexedImage(16, 16, original);

            IndexColorModel colorModel = IndexImage.getIndexColorModel(image, 2, IndexImage.DITHER_NONE);

            assertEquals(2, colorModel.getMapSize());
            assertEquals(2, colors(colorModel).size());
        }

        @Test
        @DisplayName("Should add a transparent index when bitmask transparency is requested")
        void addsTransparentIndexForBitmaskTransparency() {
            BufferedImage image = stripedImage(16, 16, RED, GREEN, BLUE, WHITE);

            IndexColorModel colorModel = IndexImage.getIndexColorModel(image, 16, IndexImage.TRANSPARENCY_BITMASK);

            assertEquals(5, colorModel.getMapSize());
            assertEquals(4, colorModel.getTransparentPixel());
            assertEquals(Transparency.BITMASK, colorModel.getTransparency());
            assertEquals(0, colorModel.getRGB(colorModel.getTransparentPixel()) >>> 24);

            Set<Integer> opaque = colors(colorModel);
            opaque.remove(0);
            assertEquals(new LinkedHashSet<>(Arrays.asList(RED, GREEN, BLUE, WHITE)), opaque);
        }

        @Test
        @DisplayName("Should ignore the alpha channel of the image when transparency is not requested")
        void ignoresAlphaWithoutTransparencyHint() {
            BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
            for (int y = 0; y < image.getHeight(); y++) {
                for (int x = 0; x < image.getWidth(); x++) {
                    image.setRGB(x, y, x < 8 ? TRANSPARENT_RED : GREEN);
                }
            }

            IndexColorModel colorModel = IndexImage.getIndexColorModel(image, 16, IndexImage.DITHER_NONE);

            assertEquals(2, colorModel.getMapSize());
            assertEquals(-1, colorModel.getTransparentPixel());
            assertEquals(Transparency.OPAQUE, colorModel.getTransparency());
            assertEquals(new LinkedHashSet<>(Arrays.asList(RED, GREEN)), colors(colorModel));
        }

        @Test
        @DisplayName("Should create a palette for an Image that is not a RenderedImage")
        void nonRenderedImage() {
            int[] pixels = new int[16];
            for (int y = 0; y < 4; y++) {
                for (int x = 0; x < 4; x++) {
                    pixels[y * 4 + x] = x < 2 ? 0xFF0000 : 0x0000FF;
                }
            }

            Image image = Toolkit.getDefaultToolkit().createImage(new MemoryImageSource(4, 4, pixels, 0, 4));

            IndexColorModel colorModel = IndexImage.getIndexColorModel(image, 16, IndexImage.DITHER_NONE);

            assertEquals(2, colorModel.getMapSize());
            assertEquals(new LinkedHashSet<>(Arrays.asList(RED, BLUE)), colors(colorModel));
        }

        @Test
        @DisplayName("Should handle large images when color selection is prioritized for speed")
        void largeImageWithFastColorSelection() {
            BufferedImage image = stripedImage(200, 200, RED, BLUE);

            IndexColorModel colorModel = IndexImage.getIndexColorModel(image, 256, IndexImage.COLOR_SELECTION_FAST);

            assertEquals(2, colorModel.getMapSize());
            assertEquals(new LinkedHashSet<>(Arrays.asList(RED, BLUE)), colors(colorModel));
        }

        @Test
        @DisplayName("Should create a full palette for an image with many colors")
        void manyColorImageGivesFullPalette() {
            BufferedImage image = gradientImage(64, 64);

            for (int hints : new int[]{IndexImage.COLOR_SELECTION_FAST, IndexImage.COLOR_SELECTION_QUALITY}) {
                IndexColorModel colorModel = IndexImage.getIndexColorModel(image, 256, hints);

                assertEquals(256, colorModel.getMapSize(), "hints: 0x" + Integer.toHexString(hints));
                assertEquals(256, colors(colorModel).size(), "Duplicates in palette, hints: 0x" + Integer.toHexString(hints));
                assertEquals(Transparency.OPAQUE, colorModel.getTransparency());
            }
        }

        @Test
        @DisplayName("Should honor the deprecated boolean 'fast' flag")
        @SuppressWarnings("deprecation")
        void deprecatedBooleanHint() {
            BufferedImage image = stripedImage(16, 16, RED, GREEN, BLUE, WHITE);

            assertEquals(4, IndexImage.getIndexColorModel(image, 16, true).getMapSize());
            assertEquals(4, IndexImage.getIndexColorModel(image, 16, false).getMapSize());
        }

        @Test
        @DisplayName("Should throw IllegalArgumentException for a null image")
        void nullImageThrows() {
            assertThrows(IllegalArgumentException.class,
                    () -> IndexImage.getIndexColorModel(null, 256, IndexImage.DITHER_DEFAULT));
        }
    }

    @Nested
    @DisplayName("getIndexedImage()")
    class GetIndexedImage {

        @Test
        @DisplayName("Should preserve the exact colors when the palette contains all image colors")
        void preservesExactColors() {
            BufferedImage image = stripedImage(16, 16, RED, GREEN, BLUE, WHITE);

            BufferedImage indexed = IndexImage.getIndexedImage(image);

            assertNotSame(image, indexed);
            assertEquals(BufferedImage.TYPE_BYTE_INDEXED, indexed.getType());
            assertPixelsPreserved(image, indexed);
            assertEquals(4, colorModel(indexed).getMapSize());
        }

        @Test
        @DisplayName("Should use TYPE_BYTE_BINARY for images with only two colors")
        void usesByteBinaryForTwoColors() {
            BufferedImage image = stripedImage(16, 16, BLACK, WHITE);

            BufferedImage indexed = IndexImage.getIndexedImage(image);

            assertEquals(BufferedImage.TYPE_BYTE_BINARY, indexed.getType());
            assertEquals(2, colorModel(indexed).getMapSize());
            assertPixelsPreserved(image, indexed);
        }

        @Test
        @DisplayName("Should preserve the exact colors when the requested number of colors is sufficient")
        void preservesExactColorsWithRequestedNumberOfColors() {
            BufferedImage image = stripedImage(16, 16, RED, GREEN, BLUE, WHITE);

            BufferedImage indexed = IndexImage.getIndexedImage(image, 4, IndexImage.DITHER_NONE);

            assertEquals(4, colorModel(indexed).getMapSize());
            assertPixelsPreserved(image, indexed);
        }

        @Test
        @DisplayName("Should use the requested (reduced) number of colors")
        void usesRequestedNumberOfColors() {
            BufferedImage image = stripedImage(16, 16, RED, GREEN, BLUE, WHITE);

            BufferedImage threeColors = IndexImage.getIndexedImage(image, 3, IndexImage.DITHER_NONE);
            assertEquals(3, colorModel(threeColors).getMapSize());
            assertOnlyPaletteColors(threeColors);
            assertEquals(image.getWidth(), threeColors.getWidth());
            assertEquals(image.getHeight(), threeColors.getHeight());

            BufferedImage twoColors = IndexImage.getIndexedImage(image, 2, IndexImage.DITHER_NONE);
            assertEquals(BufferedImage.TYPE_BYTE_BINARY, twoColors.getType());
            assertEquals(2, colorModel(twoColors).getMapSize());
            assertOnlyPaletteColors(twoColors);
        }

        @Test
        @DisplayName("Should use an explicitly supplied IndexColorModel")
        void usesSuppliedIndexColorModel() {
            BufferedImage image = stripedImage(16, 16, RED, GREEN, BLUE);
            IndexColorModel colors = palette(BLUE, GREEN, RED);

            BufferedImage indexed = IndexImage.getIndexedImage(image, colors, IndexImage.DITHER_NONE);

            assertEquals(3, colorModel(indexed).getMapSize());
            assertEquals(colors(colors), colors(colorModel(indexed)));
            assertPixelsPreserved(image, indexed);
        }

        @Test
        @DisplayName("Should use the colors of a palette image")
        void usesPaletteImage() {
            BufferedImage image = stripedImage(16, 16, RED, GREEN, BLUE);
            BufferedImage paletteImage = stripedImage(16, 16, RED, GREEN, BLUE);

            BufferedImage indexed = IndexImage.getIndexedImage(image, paletteImage, IndexImage.DITHER_NONE);

            assertEquals(3, colorModel(indexed).getMapSize());
            assertPixelsPreserved(image, indexed);
        }

        @Test
        @DisplayName("Should use the palette of an indexed palette image")
        void usesIndexedPaletteImage() {
            BufferedImage image = stripedImage(16, 16, RED, GREEN, BLUE);
            BufferedImage paletteImage = indexedImage(16, 16, palette(RED, GREEN, BLUE));

            BufferedImage indexed = IndexImage.getIndexedImage(image, paletteImage, IndexImage.DITHER_NONE);

            assertEquals(3, colorModel(indexed).getMapSize());
            assertPixelsPreserved(image, indexed);
        }

        @Test
        @DisplayName("Should dither an image into the colors of the palette")
        void diffusionDitherUsesOnlyPaletteColors() {
            BufferedImage image = gradientImage(32, 32);
            IndexColorModel blackAndWhite = palette(BLACK, WHITE);

            BufferedImage dithered = IndexImage.getIndexedImage(image, blackAndWhite, null, IndexImage.DITHER_DIFFUSION);
            BufferedImage notDithered = IndexImage.getIndexedImage(image, blackAndWhite, null, IndexImage.DITHER_NONE);

            assertEquals(BufferedImage.TYPE_BYTE_BINARY, dithered.getType());
            assertEquals(image.getWidth(), dithered.getWidth());
            assertEquals(image.getHeight(), dithered.getHeight());
            assertOnlyPaletteColors(dithered);
            assertOnlyPaletteColors(notDithered);

            // The gradient is smooth, so error diffusion must produce a different (dithered) result
            int differingPixels = countDifferences(dithered, notDithered);
            assertTrue(differingPixels > 0, "Dithering had no visible effect");
        }

        @Test
        @DisplayName("Should dither an image using alternating scans")
        void diffusionDitherWithAlternateScans() {
            BufferedImage image = gradientImage(32, 32);
            IndexColorModel blackAndWhite = palette(BLACK, WHITE);

            BufferedImage alternating = IndexImage.getIndexedImage(image, blackAndWhite, null,
                    IndexImage.DITHER_DIFFUSION_ALTSCANS);

            assertEquals(image.getWidth(), alternating.getWidth());
            assertEquals(image.getHeight(), alternating.getHeight());
            assertOnlyPaletteColors(alternating);

            // Alternating scans is a distinct diffusion mode, and should give a different result for this image
            BufferedImage dithered = IndexImage.getIndexedImage(image, blackAndWhite, null, IndexImage.DITHER_DIFFUSION);
            int differingPixels = countDifferences(alternating, dithered);
            assertTrue(differingPixels > 0, "Alternating scans had no visible effect");
        }

        @Test
        @DisplayName("Should use the default dither when a full palette is requested")
        void defaultDitherWithFullPalette() {
            BufferedImage image = gradientImage(64, 64);

            BufferedImage indexed = IndexImage.getIndexedImage(image);

            assertEquals(BufferedImage.TYPE_BYTE_INDEXED, indexed.getType());
            assertEquals(256, colorModel(indexed).getMapSize());
            assertEquals(image.getWidth(), indexed.getWidth());
            assertEquals(image.getHeight(), indexed.getHeight());
            assertOnlyPaletteColors(indexed);
        }

        @Test
        @DisplayName("Should replace transparent pixels with the matte color")
        void matteReplacesTransparentPixels() {
            BufferedImage image = new BufferedImage(8, 8, BufferedImage.TYPE_INT_ARGB);
            for (int y = 0; y < image.getHeight(); y++) {
                for (int x = 0; x < image.getWidth(); x++) {
                    image.setRGB(x, y, x < 4 ? TRANSPARENT_RED : GREEN);
                }
            }

            BufferedImage indexed = IndexImage.getIndexedImage(image, 256, Color.BLUE, IndexImage.DITHER_NONE);

            assertEquals(BLUE, indexed.getRGB(0, 0));
            assertEquals(GREEN, indexed.getRGB(7, 0));
            assertEquals(new LinkedHashSet<>(Arrays.asList(BLUE, GREEN)), colors(colorModel(indexed)));
            assertEquals(Transparency.OPAQUE, colorModel(indexed).getTransparency());
        }

        @Test
        @DisplayName("Should composite the matte color with semi-transparent pixels")
        void matteCompositesWithSemiTransparentPixels() {
            BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
            for (int y = 0; y < image.getHeight(); y++) {
                for (int x = 0; x < image.getWidth(); x++) {
                    int color;

                    if (x < 4) {
                        color = 0x00FF0000; // Fully transparent red
                    }
                    else if (x < 8) {
                        color = 0x80FF0000; // 50% transparent red
                    }
                    else {
                        color = RED; // Opaque red
                    }

                    image.setRGB(x, y, color);
                }
            }

            BufferedImage withoutMatte = IndexImage.getIndexedImage(image, 256,
                    IndexImage.DITHER_NONE | IndexImage.TRANSPARENCY_BITMASK);
            BufferedImage withMatte = IndexImage.getIndexedImage(image, 256, Color.BLUE,
                    IndexImage.DITHER_NONE | IndexImage.TRANSPARENCY_BITMASK);

            // Without a matte, the semi-transparent pixel keeps its color
            assertEquals(RED, withoutMatte.getRGB(4, 0));

            // Fully transparent pixels stay transparent, also when a matte is supplied
            assertEquals(0, withMatte.getRGB(0, 0) >>> 24);

            // With a matte, the semi-transparent pixel is composited onto the matte color
            int blended = withMatte.getRGB(4, 0);
            assertEquals(0xFF, blended >>> 24, "Should be opaque: " + Integer.toHexString(blended));
            assertNotEquals(RED, blended);
            assertTrue(Math.abs(((blended >> 16) & 0xFF) - 0x80) < 0x10,
                    "Red component should be about half: " + Integer.toHexString(blended));
            assertTrue(Math.abs((blended & 0xFF) - 0x80) < 0x10,
                    "Matte color should be visible: " + Integer.toHexString(blended));

            // Opaque pixels are not affected by the matte
            assertEquals(RED, withMatte.getRGB(8, 0));
        }

        @Test
        @DisplayName("Should apply bitmask transparency to the indexed image")
        void appliesBitmaskTransparency() {
