@DisplayName("IndexImage")
class IndexImageTests {

    private static final int RED = 0xFFFF0000;
    private static final int GREEN = 0xFF00FF00;
    private static final int BLUE = 0xFF0000FF;
    private static final int WHITE = 0xFFFFFFFF;
    private static final int BLACK = 0xFF000000;

    private static final int TRANSPARENT_RED = 0x00FF0000;

    /**
     * Creates a new {@code TYPE_INT_RGB} image where the colors are painted in diagonal stripes.
     */
    private static BufferedImage stripedImage(int width, int height, int... rgb) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                image.setRGB(x, y, rgb[(x + y) % rgb.length]);
            }
        }

        return image;
    }

    /**
     * Creates a new {@code TYPE_INT_RGB} image containing a smooth (many colors) gradient.
     */
    private static BufferedImage gradientImage(int width, int height) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int r = (x * 255) / (width - 1);
                int g = (y * 255) / (height - 1);
                int b = ((x + y) * 255) / (width + height - 2);
                image.setRGB(x, y, (r << 16) | (g << 8) | b);
            }
        }

        return image;
    }

    /**
     * Creates an 8 bit {@code IndexColorModel} (palette) from the given opaque RGB values.
     */
    private static IndexColorModel palette(int... rgb) {
        byte[] r = new byte[rgb.length];
        byte[] g = new byte[rgb.length];
        byte[] b = new byte[rgb.length];

        for (int i = 0; i < rgb.length; i++) {
            r[i] = (byte) ((rgb[i] >> 16) & 0xFF);
            g[i] = (byte) ((rgb[i] >> 8) & 0xFF);
            b[i] = (byte) (rgb[i] & 0xFF);
        }

        return new IndexColorModel(8, rgb.length, r, g, b);
    }

    /**
     * Creates a {@code TYPE_BYTE_INDEXED} image using all the colors of the given palette.
     */
    private static BufferedImage indexedImage(int width, int height, IndexColorModel colors) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_BYTE_INDEXED, colors);

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                image.getRaster().setSample(x, y, 0, (x + y) % colors.getMapSize());
            }
        }

        return image;
    }

    /**
     * Returns the ARGB color of every pixel in the given image.
     */
    private static Set<Integer> pixels(BufferedImage image) {
        Set<Integer> result = new LinkedHashSet<>();

        for (int y = 0; y < image.getHeight(); y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                result.add(image.getRGB(x, y));
            }
        }

        return result;
    }

    /**
     * Returns the colors (including alpha) contained in the given color model.
     */
    private static Set<Integer> colors(IndexColorModel colorModel) {
        Set<Integer> result = new LinkedHashSet<>();

        for (int i = 0; i < colorModel.getMapSize(); i++) {
            result.add(colorModel.getRGB(i));
        }

        return result;
    }

    /**
     * Counts the number of pixel positions where the two images differ.
     */
    private static int countDifferences(BufferedImage first, BufferedImage second) {
        assertEquals(first.getWidth(), second.getWidth());
        assertEquals(first.getHeight(), second.getHeight());

        int count = 0;

        for (int y = 0; y < first.getHeight(); y++) {
            for (int x = 0; x < first.getWidth(); x++) {
                if (first.getRGB(x, y) != second.getRGB(x, y)) {
                    count++;
                }
            }
        }

        return count;
    }

    private static IndexColorModel colorModel(BufferedImage image) {
        assertTrue(image.getColorModel() instanceof IndexColorModel, "Not an indexed image: " + image);
        return (IndexColorModel) image.getColorModel();
    }

    private static void assertPixelsPreserved(BufferedImage expected, BufferedImage actual) {
        assertEquals(expected.getWidth(), actual.getWidth());
        assertEquals(expected.getHeight(), actual.getHeight());

        for (int y = 0; y < expected.getHeight(); y++) {
            for (int x = 0; x < expected.getWidth(); x++) {
                assertEquals(expected.getRGB(x, y), actual.getRGB(x, y), "Pixel (" + x + ", " + y + ") differs");
            }
        }
    }

    private static void assertOnlyPaletteColors(BufferedImage image) {
        Set<Integer> paletteColors = colors(colorModel(image));
        Set<Integer> imageColors = pixels(image);

        for (Integer color : imageColors) {
            assertTrue(paletteColors.contains(color),
                    "Pixel color " + Integer.toHexString(color) + " not in palette " + paletteColors);
        }
    }

