        @DisplayName("Should dither an image into the colors of the palette")
        void diffusionDitherUsesOnlyPaletteColors() {
            BufferedImage image = gradientImage(32, 32);
            IndexColorModel blackAndWhite = palette(BLACK, WHITE);

            BufferedImage dithered = IndexImage.getIndexedImage(image, blackAndWhite, null, IndexImage.DITHER_DIFFUSION);
            BufferedImage notDithered = IndexImage.getIndexedImage(image, blackAndWhite, null, IndexImage.DITHER_NONE);

            assertEquals(BufferedImage.TYPE_BYTE_BINARY, dithered.getType());
            assertEquals(image.getWidth(), dithered.getWidth());
            assertEquals(image.getHeight(), dithered.getHeight());
            assertOnlyPaletteColors(dithered);
            assertOnlyPaletteColors(notDithered);

            // The gradient is smooth, so error diffusion must produce a different (dithered) result
            int differingPixels = countDifferences(dithered, notDithered);
            assertTrue(differingPixels > 0, "Dithering had no visible effect");
        }

