            for (int y = 0; y < image.getHeight(); y++) {
                for (int x = 0; x < image.getWidth(); x++) {
                    image.setRGB(x, y, x < 4 ? TRANSPARENT_RED : GREEN);
                }
            }

            BufferedImage indexed = IndexImage.getIndexedImage(image, 256, Color.BLUE, IndexImage.DITHER_NONE);

            assertEquals(BLUE, indexed.getRGB(0, 0));
            assertEquals(GREEN, indexed.getRGB(7, 0));
            assertEquals(new LinkedHashSet<>(Arrays.asList(BLUE, GREEN)), colors(colorModel(indexed)));
            assertEquals(Transparency.OPAQUE, colorModel(indexed).getTransparency());
        }

        @Test
        @DisplayName("Should composite the matte color with semi-transparent pixels")
        void matteCompositesWithSemiTransparentPixels() {
            BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
            for (int y = 0; y < image.getHeight(); y++) {
                for (int x = 0; x < image.getWidth(); x++) {
                    int color;

                    if (x < 4) {
                        color = 0x00FF0000; // Fully transparent red
                    }
                    else if (x < 8) {
                        color = 0x80FF0000; // 50% transparent red
                    }
                    else {
                        color = RED; // Opaque red
                    }

                    image.setRGB(x, y, color);
                }
            }

            BufferedImage withoutMatte = IndexImage.getIndexedImage(image, 256,
                    IndexImage.DITHER_NONE | IndexImage.TRANSPARENCY_BITMASK);
            BufferedImage withMatte = IndexImage.getIndexedImage(image, 256, Color.BLUE,
                    IndexImage.DITHER_NONE | IndexImage.TRANSPARENCY_BITMASK);

            // Without a matte, the semi-transparent pixel keeps its color
            assertEquals(RED, withoutMatte.getRGB(4, 0));

            // Fully transparent pixels stay transparent, also when a matte is supplied
            assertEquals(0, withMatte.getRGB(0, 0) >>> 24);

            // With a matte, the semi-transparent pixel is composited onto the matte color
            int blended = withMatte.getRGB(4, 0);
            assertEquals(0xFF, blended >>> 24, "Should be opaque: " + Integer.toHexString(blended));
            assertNotEquals(RED, blended);
            assertTrue(Math.abs(((blended >> 16) & 0xFF) - 0x80) < 0x10,
                    "Red component should be about half: " + Integer.toHexString(blended));
            assertTrue(Math.abs((blended & 0xFF) - 0x80) < 0x10,
                    "Matte color should be visible: " + Integer.toHexString(blended));

