            assertEquals(RED, withMatte.getRGB(8, 0));
        }

        @Test
        @DisplayName("Should apply bitmask transparency to the indexed image")
        void appliesBitmaskTransparency() {
            BufferedImage image = new BufferedImage(8, 8, BufferedImage.TYPE_INT_ARGB);
            for (int y = 0; y < image.getHeight(); y++) {
                for (int x = 0; x < image.getWidth(); x++) {
                    image.setRGB(x, y, x < 4 ? TRANSPARENT_RED : GREEN);
                }
            }

            BufferedImage indexed = IndexImage.getIndexedImage(image, 256,
                    IndexImage.DITHER_NONE | IndexImage.TRANSPARENCY_BITMASK);

            IndexColorModel colorModel = colorModel(indexed);
            assertEquals(Transparency.BITMASK, colorModel.getTransparency());
            assertTrue(colorModel.getTransparentPixel() >= 0);

            // Transparent pixels are mapped to the transparent index
            assertEquals(colorModel.getTransparentPixel(), indexed.getRaster().getSample(0, 0, 0));
            assertEquals(0, indexed.getRGB(0, 0) >>> 24);

            // Opaque pixels are unaffected
            assertEquals(GREEN, indexed.getRGB(7, 0));
