            assertThrows(IllegalArgumentException.class,
                    () -> IndexImage.getIndexedImage(image, (Image) null, IndexImage.DITHER_NONE));
        }
    }

    @Nested
    @DisplayName("main(String[])")
    class CommandLine {

        @Test
        @DisplayName("Should convert an image file to an indexed image file")
        void convertsImageFile(@TempDir Path tempDir) throws IOException {
            BufferedImage source = stripedImage(16, 16, RED, GREEN);

            File input = tempDir.resolve("input.png").toFile();
            assertTrue(ImageIO.write(source, "png", input));

            File output = tempDir.resolve("output.png").toFile();
            assertFalse(output.exists());

            IndexImage.main(new String[]{input.getAbsolutePath(), output.getAbsolutePath()});

            assertTrue(output.exists(), "Output file was not created");
            assertTrue(output.length() > 0, "Output file is empty");

            BufferedImage converted = ImageIO.read(output);
            assertNotNull(converted);
            assertEquals(source.getWidth(), converted.getWidth());
            assertEquals(source.getHeight(), converted.getHeight());
            assertTrue(converted.getColorModel() instanceof IndexColorModel,
                    "Expected indexed output, was: " + converted.getColorModel());

            for (Integer pixel : pixels(converted)) {
                assertTrue(pixel == RED || pixel == GREEN, "Unexpected color: " + Integer.toHexString(pixel));
            }
        }
    }
