    @Test
    public void testReadSendsProgressEvents() throws IOException {
        setInput(new Bmp(2, 3, 24).pixels(rgb24(2, 3, false, new int[][]{
                {1, 2}, {3, 4}, {5, 6}
        })).build());

        final List<String> events = new ArrayList<>();
        reader.addIIOReadProgressListener(new RecordingProgressListener(events));

        reader.read(0, null);

        assertTrue(events.contains("imageStarted"), "Events: " + events);
        assertTrue(events.contains("imageProgress"), "Events: " + events);
        assertTrue(events.contains("imageComplete"), "Events: " + events);
        assertEquals("imageStarted", events.get(0), "Events: " + events);
        assertEquals("imageComplete", events.get(events.size() - 1), "Events: " + events);
    }

    @Test
    public void testAbortReportsReadAborted() throws IOException {
        setInput(new Bmp(2, 3, 24).pixels(rgb24(2, 3, false, new int[][]{
                {0x010101, 0x020202},
                {0x030303, 0x040404},
                {0x050505, 0x060606}
        })).build());

        final List<String> events = new ArrayList<>();
        reader.addIIOReadProgressListener(new RecordingProgressListener(events) {
            @Override
            public void imageStarted(ImageReader source, int imageIndex) {
                super.imageStarted(source, imageIndex);
                source.abort();
            }
        });

        BufferedImage image = reader.read(0, null);

        assertNotNull(image);
        assertEquals(2, image.getWidth());
        assertEquals(3, image.getHeight());
        assertTrue(events.contains("readAborted"), "Events: " + events);

        // Reading must stop after the first row: the bottom row of the bottom-up image is decoded,
        // the remaining rows are left untouched
        assertEquals(0xFF050505, image.getRGB(0, 2));
        assertEquals(0xFF060606, image.getRGB(1, 2));
        assertEquals(0xFF000000, image.getRGB(0, 0));
        assertEquals(0xFF000000, image.getRGB(1, 1));
    }

