    @Test
    public void testImageMetadataContainsHeaderValues() throws IOException {
        setInput(new Bmp(5, 3, 24).pixels(new byte[((24 * 5 + 31) / 32) * 4 * 3]).build());

        IIOMetadata metadata = reader.getImageMetadata(0);
        assertNotNull(metadata);

        IIOMetadataNode root = (IIOMetadataNode) metadata.getAsTree("javax_imageio_bmp_1.0");
        assertEquals("javax_imageio_bmp_1.0", root.getNodeName());

        assertEquals("5", nodeValue(root, "Width"));
        assertEquals("3", nodeValue(root, "Height"));
        assertEquals("24", nodeValue(root, "BitsPerPixel"));
        assertEquals("0", nodeValue(root, "Compression"));
        assertEquals("BMP v. 3.x", nodeValue(root, "BMPVersion"));

        IIOMetadataNode pixelsPerMeter = (IIOMetadataNode) root.getElementsByTagName("PixelsPerMeter").item(0);
        assertNotNull(pixelsPerMeter);
        assertEquals("2835", nodeValue(pixelsPerMeter, "X"));
        assertEquals("2835", nodeValue(pixelsPerMeter, "Y"));

        // No palette for true color images
        assertEquals(0, root.getElementsByTagName("Palette").getLength());
    }

    @Test
    public void testImageMetadataContainsPalette() throws IOException {
        setInput(new Bmp(2, 1, 8).palette(PALETTE).pixels(leRows(2, 1, 1, false, new int[][]{{0, 1}}, 4)).build());

        IIOMetadata metadata = reader.getImageMetadata(0);
        IIOMetadataNode root = (IIOMetadataNode) metadata.getAsTree("javax_imageio_bmp_1.0");

        IIOMetadataNode palette = (IIOMetadataNode) root.getElementsByTagName("Palette").item(0);
        assertNotNull(palette, "Expected a Palette node");

        assertEquals(4, palette.getElementsByTagName("PaletteEntry").getLength());
        IIOMetadataNode firstEntry = (IIOMetadataNode) palette.getElementsByTagName("PaletteEntry").item(0);
        // Palette entries are reported as signed bytes
        assertEquals("-1", nodeValue(firstEntry, "Red"));
        assertEquals("0", nodeValue(firstEntry, "Green"));
        assertEquals("0", nodeValue(firstEntry, "Blue"));

        IIOMetadataNode secondEntry = (IIOMetadataNode) palette.getElementsByTagName("PaletteEntry").item(1);
        assertEquals("0", nodeValue(secondEntry, "Red"));
        assertEquals("-1", nodeValue(secondEntry, "Green"));
        assertEquals("0", nodeValue(secondEntry, "Blue"));
    }

    @Test
    public void testImageMetadataIncludesPaletteForTrueColorImageWithColorTable() throws IOException {
        // 24 bit images may still have a (non used) color table, reported in the metadata only
        setInput(new Bmp(1, 1, 24).palette(PALETTE)
                .pixels(rgb24(1, 1, false, new int[][]{{0x00FF00}})).build());

        IIOMetadataNode root = (IIOMetadataNode) reader.getImageMetadata(0).getAsTree("javax_imageio_bmp_1.0");

        assertEquals("24", nodeValue(root, "BitsPerPixel"));

        IIOMetadataNode palette = (IIOMetadataNode) root.getElementsByTagName("Palette").item(0);
        assertNotNull(palette, "Expected a Palette node");
        assertEquals(PALETTE.length, palette.getElementsByTagName("PaletteEntry").getLength());

        // The color table does not affect decoding, the image is still read as true color
        assertEquals(BufferedImage.TYPE_3BYTE_BGR, reader.getRawImageType(0).getBufferedImageType());
        assertEquals(0xFF00FF00, reader.read(0, null).getRGB(0, 0));
    }

