    @Test
    public void testReadPngCompressedBmpDelegatesToPngReader() throws IOException {
        byte[] png = writeImage("png", 4, 3);

        // Trailing junk must be ignored, the delegate is bounded by the image size in the DIB header
        byte[] trailing = new byte[16];
        byte[] container = new Bmp(4, 3, 0).compression(COMPRESSION_PNG)
                .imageSize(png.length)
                .pixels(concat(png, trailing)).build();

