    private static String nodeValue(IIOMetadataNode parent, String name) {
        IIOMetadataNode node = (IIOMetadataNode) parent.getElementsByTagName(name).item(0);
        assertNotNull(node, "Missing node: " + name);
        return node.getNodeValue();
