        // 1 bit per pixel allows only 2 palette entries, but the header claims 4
        setInput(new Bmp(4, 1, 1).palette(PALETTE).colorsUsed(4).pixels(packed(4, 1, 1, false, new int[][]{
                {0, 1, 0, 1}
