        final List<String> warnings = new ArrayList<>();
        reader.addIIOReadWarningListener(new IIOReadWarningListener() {
            @Override
            public void warningOccurred(ImageReader source, String warning) {
                warnings.add(warning);
            }
        });

        BufferedImage image = reader.read(0, null);

        assertEquals(1, warnings.size(), "Warnings: " + warnings);
        assertTrue(warnings.get(0).contains("Color map contains more colors than raster allows"),
                "Unexpected warning: " + warnings.get(0));
        assertEquals(PALETTE[0], image.getRGB(0, 0));
        assertEquals(PALETTE[1], image.getRGB(1, 0));
    }

