    private static File resourceDir(String path) throws Exception {
        return new File(BMPImageReaderTests.class.getResource(path).toURI());
    }

    private static byte[] readFile(File file) throws IOException {
        return Files.readAllBytes(file.toPath());
    }

    private static String nodeValue(IIOMetadataNode parent, String name) {
        IIOMetadataNode node = (IIOMetadataNode) parent.getElementsByTagName(name).item(0);
        assertNotNull(node, "Missing node: " + name);
        return node.getNodeValue();
    }

    private static byte[] writeImage(final String format, final int width, final int height) throws IOException {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                image.setRGB(x, y, 0x100000 * ((x + y) % 8));
            }
        }

        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        assertTrue(ImageIO.write(image, format, buffer), "No writer for " + format);

        return buffer.toByteArray();
    }

    private static byte[] concat(byte[] a, byte[] b) {
        byte[] result = new byte[a.length + b.length];
        System.arraycopy(a, 0, result, 0, a.length);
        System.arraycopy(b, 0, result, a.length, b.length);
        return result;
    }

    private static int rowSize(int width, int bitCount) {
        return ((bitCount * width + 31) / 32) * 4;
    }

    /** Creates a 24 bit BGR row padded raster from RGB values, in top-down image order. */
    private static byte[] rgb24(int width, int height, boolean topDown, int[][] rgb) {
        return leRows(width, height, 3, topDown, rgb, rowSize(width, 24));
    }

    /**
     * Creates a raster where each sample is written as a little endian value of
     * {@code bytesPerSample} bytes. Used for 16, 24 and 32 bit samples.
     */
    private static byte[] leRows(int width, int height, int bytesPerSample, boolean topDown, int[][] values, int rowSize) {
        byte[] data = new byte[rowSize * height];
        for (int y = 0; y < height; y++) {
            int fileRow = topDown ? y : height - 1 - y;
            for (int x = 0; x < width; x++) {
                int value = values[y][x];
                int offset = fileRow * rowSize + x * bytesPerSample;
                for (int b = 0; b < bytesPerSample; b++) {
                    data[offset + b] = (byte) (value >>> (8 * b));
                }
            }
        }

        return data;
    }

    /** Creates a packed raster for 1, 2, 4 or 8 bit samples (MSB first). */
    private static byte[] packed(int width, int height, int bits, boolean topDown, int[][] values) {
        int rowSize = rowSize(width, bits);
        byte[] data = new byte[rowSize * height];

        for (int y = 0; y < height; y++) {
            int fileRow = topDown ? y : height - 1 - y;
            for (int x = 0; x < width; x++) {
                int value = values[y][x];
                int bitOffset = x * bits;
                int byteIndex = fileRow * rowSize + bitOffset / 8;
                int shift = 8 - bits - (bitOffset % 8);
                data[byteIndex] |= (byte) ((value & ((1 << bits) - 1)) << shift);
            }
        }

        return data;
    }

    /** Simple in-memory BMP file builder. */
    private static final class Bmp {
        private final int width;
        private final int height;
        private final int bitCount;

        private int planes = 1;
        private int compression = COMPRESSION_RGB;
        private int headerSize = INFO_HEADER_SIZE;
        private boolean topDown;
        private int[] palette;
        private int colorsUsed = -1;
        private int[] masks;
        private int imageSize = -1;
        private int pixelOffsetDelta;
        private byte[] pixels = new byte[0];

        Bmp(int width, int height, int bitCount) {
            this.width = width;
            this.height = height;
            this.bitCount = bitCount;
        }

        Bmp planes(int planes) {
            this.planes = planes;
            return this;
        }

        Bmp compression(int compression) {
            this.compression = compression;
            return this;
        }

        Bmp headerSize(int headerSize) {
            this.headerSize = headerSize;
            return this;
        }

        Bmp topDown() {
            this.topDown = true;
            return this;
        }

        Bmp palette(int... argb) {
            this.palette = argb;
            return this;
        }

        Bmp colorsUsed(int colorsUsed) {
            this.colorsUsed = colorsUsed;
            return this;
        }

        Bmp masks(int... masks) {
            this.masks = masks;
            return this;
        }

        Bmp imageSize(int imageSize) {
            this.imageSize = imageSize;
            return this;
        }

        Bmp pixels(byte[] pixels) {
            this.pixels = pixels;
            return this;
        }

        Bmp pixelOffsetDelta(int delta) {
            this.pixelOffsetDelta = delta;
            return this;
        }

        byte[] build() {
            boolean headerContainsMasks = headerSize == V4_HEADER_SIZE;
            int maskBytes = !headerContainsMasks && masks != null ? masks.length * 4 : 0;
            int paletteBytes = palette == null ? 0 : palette.length * (headerSize == CORE_HEADER_SIZE ? 3 : 4);
            int pixelOffset = FILE_HEADER_SIZE + headerSize + maskBytes + paletteBytes + pixelOffsetDelta;
            int fileSize = pixelOffset + pixels.length;

            ByteArrayOutputStream out = new ByteArrayOutputStream();

            // BITMAPFILEHEADER
            out.write('B');
            out.write('M');
            writeInt(out, fileSize);
            writeInt(out, 0);
            writeInt(out, pixelOffset);

            // DIB header
            writeInt(out, headerSize);

            if (headerSize == CORE_HEADER_SIZE) {
                writeShort(out, width);
                writeShort(out, topDown ? -height : height);
                writeShort(out, planes);
                writeShort(out, bitCount);
            }
            else {
                writeInt(out, width);
                writeInt(out, topDown ? -height : height);
                writeShort(out, planes);
                writeShort(out, bitCount);
                writeInt(out, compression);
                writeInt(out, imageSize >= 0 ? imageSize : rowSize(width, bitCount) * height);
                writeInt(out, 2835);
                writeInt(out, 2835);
                writeInt(out, colorsUsed >= 0 ? colorsUsed : (palette == null ? 0 : palette.length));
                writeInt(out, 0);

                if (maskBytes > 0) {
                    for (int mask : masks) {
                        writeInt(out, mask);
                    }
                }

                if (headerContainsMasks) {
                    int[] headerMasks = masks != null
                                        ? masks
                                        : new int[] {0x00FF0000, 0x0000FF00, 0x000000FF, 0xFF000000};
                    for (int mask : headerMasks) {
                        writeInt(out, mask);
                    }
                    writeInt(out, 0x73524742); // 'sRGB'
                    for (int i = 0; i < 9; i++) { // CIE XYZ endpoints
                        writeInt(out, 0);
                    }
                    for (int i = 0; i < 3; i++) { // Gamma
                        writeInt(out, 0);
                    }
                }

                // Pad to the declared header size (for truncated/extended headers)
                while (headerSize > out.size() - FILE_HEADER_SIZE) {
                    out.write(0);
                }
            }

            // Palette, BGR(A) ordering
            if (palette != null) {
                for (int argb : palette) {
                    out.write(argb & 0xFF);
                    out.write(argb >> 8 & 0xFF);
                    out.write(argb >> 16 & 0xFF);
                    if (headerSize != CORE_HEADER_SIZE) {
                        out.write(0);
                    }
                }
            }

            out.write(pixels, 0, pixels.length);

            return out.toByteArray();
        }

        private static void writeInt(ByteArrayOutputStream out, int value) {
            out.write(value & 0xFF);
            out.write(value >> 8 & 0xFF);
            out.write(value >> 16 & 0xFF);
            out.write(value >> 24 & 0xFF);
        }

        private static void writeShort(ByteArrayOutputStream out, int value) {
            out.write(value & 0xFF);
            out.write(value >> 8 & 0xFF);
        }
    }

    private static class RecordingProgressListener implements IIOReadProgressListener {
        private final List<String> events;

        RecordingProgressListener(List<String> events) {
            this.events = events;
        }

        @Override
        public void sequenceStarted(ImageReader source, int minIndex) {
            events.add("sequenceStarted");
        }

        @Override
        public void sequenceComplete(ImageReader source) {
            events.add("sequenceComplete");
        }

        @Override
        public void imageStarted(ImageReader source, int imageIndex) {
            events.add("imageStarted");
        }

        @Override
        public void imageProgress(ImageReader source, float percentageDone) {
            events.add("imageProgress");
        }

        @Override
        public void imageComplete(ImageReader source) {
            events.add("imageComplete");
        }

        @Override
        public void thumbnailStarted(ImageReader source, int imageIndex, int thumbnailIndex) {
            events.add("thumbnailStarted");
        }

        @Override
        public void thumbnailProgress(ImageReader source, float percentageDone) {
            events.add("thumbnailProgress");
        }

        @Override
        public void thumbnailComplete(ImageReader source) {
            events.add("thumbnailComplete");
        }

        @Override
        public void readAborted(ImageReader source) {
            events.add("readAborted");
        }
    }
