        List<Segment> segments = segments(jpeg);
        return new JPEGLosslessDecoder(segments, inputStream(jpeg), listener);
    }

    private static ImageInputStream inputStream(byte[] data) {
        return new MemoryCacheImageInputStream(new ByteArrayInputStream(data));
    }

    private static List<Segment> segments(byte[] jpeg) throws IOException {
        DataInputStream data = new DataInputStream(new ByteArrayInputStream(jpeg));
        if (data.readUnsignedShort() != JPEG.SOI) {
            throw new IllegalArgumentException("Test data does not start with SOI");
        }

        List<Segment> segments = new ArrayList<>();
        while (true) {
            int marker = data.readUnsignedShort();
            if (marker == JPEG.SOS || marker == JPEG.EOI) {
                return segments;
            }

            int length = data.readUnsignedShort();
            if (marker == JPEG.DHT || marker == JPEG.DQT || marker == JPEG.DRI
                    || marker == JPEG.SOF3 || marker == JPEG.SOF7
                    || marker == JPEG.SOF11 || marker == JPEG.SOF15) {
                segments.add(Segment.read(marker, "", length, data));
            }
            else {
                skipFully(data, length - 2);
            }
        }
    }

    private static void skipFully(DataInputStream data, int count) throws IOException {
        int remaining = count;
        while (remaining > 0) {
            int skipped = data.skipBytes(remaining);
            if (skipped <= 0) {
                if (data.read() < 0) {
                    throw new IOException("Unexpected end of JPEG data");
                }
                skipped = 1;
            }
            remaining -= skipped;
        }
    }

    private static byte[] resource(String name) throws IOException {
        InputStream input = JPEGLosslessDecoderTests.class.getResourceAsStream(name);
        assertNotNull(input, "Missing test resource: " + name);
        try {
            ByteArrayOutputStream output = new ByteArrayOutputStream();
            byte[] buffer = new byte[8192];
            int read;
            while ((read = input.read(buffer)) >= 0) {
                output.write(buffer, 0, read);
            }
            return output.toByteArray();
        }
        finally {
            input.close();
        }
    }

    private static byte[] standardDcAndAcTables() throws IOException {
        return concatenate(
                huffmanTable(0x00, counts(2), new int[] {0, 1}),
                huffmanTable(0x10, counts(1), new int[] {0})
        );
    }

    private static int[] counts(int firstLength, int... moreLengths) {
        int[] counts = new int[16];
        counts[0] = firstLength;
        for (int i = 0; i < moreLengths.length; i++) {
            counts[i + 1] = moreLengths[i];
        }
        return counts;
    }

    private static byte[] huffmanTable(int tableInfo, int[] counts, int[] values) throws IOException {
        assertEquals(16, counts.length);
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        output.write(tableInfo);
        int total = 0;
        for (int count : counts) {
            assertTrue(count >= 0 && count <= 255);
            output.write(count);
            total += count;
        }
        assertEquals(total, values.length);
        for (int value : values) {
            output.write(value);
        }
        return output.toByteArray();
    }

    private static byte[] encodeGrayscaleDifferences(int... differences) throws IOException {
        BitWriter writer = new BitWriter();
        for (int difference : differences) {
            writer.writeDcDifference(difference);
        }
        return writer.toByteArray();
    }

    private static byte[] encodeInterleavedDifferences(int[][] differences, boolean includeEob) throws IOException {
        BitWriter writer = new BitWriter();
        for (int[] pixel : differences) {
            for (int difference : pixel) {
                writer.writeDcDifference(difference);
                if (includeEob) {
                    writer.writeBit(0); // One-bit AC table: zero is EOB.
                }
            }
        }
        return writer.toByteArray();
    }

    private static byte[] losslessJpeg(
            int precision, int width, int height,
            int[] frameComponents, int[] scanComponents,
            int predictor, int pointTransform, int restartInterval,
            byte[] dhtPayload, byte[] entropyData
    ) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();

        writeMarker(output, JPEG.SOI);

        ByteArrayOutputStream frame = new ByteArrayOutputStream();
        frame.write(precision);
        writeShort(frame, height);
        writeShort(frame, width);
        frame.write(frameComponents.length);
        for (int component : frameComponents) {
            frame.write(component);
            frame.write(0x11); // 1x1 sampling
            frame.write(0);    // Quantization table selector, unused for lossless.
        }
        writeSegment(output, JPEG.SOF3, frame.toByteArray());

        writeSegment(output, JPEG.DHT, dhtPayload);

        if (restartInterval != 0) {
            ByteArrayOutputStream dri = new ByteArrayOutputStream();
            writeShort(dri, restartInterval);
            writeSegment(output, JPEG.DRI, dri.toByteArray());
        }

        ByteArrayOutputStream scan = new ByteArrayOutputStream();
        scan.write(scanComponents.length);
        for (int component : scanComponents) {
            scan.write(component);
            scan.write(0); // DC table 0 and AC table 0.
        }
        scan.write(predictor);
        scan.write(0); // Spectral selection end is zero for lossless.
        scan.write(pointTransform);

        writeSegment(output, JPEG.SOS, scan.toByteArray());
        output.write(entropyData);
        writeMarker(output, JPEG.EOI);

        return output.toByteArray();
    }

    private static void writeSegment(ByteArrayOutputStream output, int marker, byte[] payload) throws IOException {
        writeMarker(output, marker);
        writeShort(output, payload.length + 2);
        output.write(payload);
    }

    private static void writeMarker(ByteArrayOutputStream output, int marker) throws IOException {
        DataOutputStream data = new DataOutputStream(output);
        data.writeShort(marker);
        data.flush();
    }

    private static void writeShort(ByteArrayOutputStream output, int value) throws IOException {
        DataOutputStream data = new DataOutputStream(output);
        data.writeShort(value);
        data.flush();
    }

    private static byte[] concatenate(byte[]... arrays) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        for (byte[] array : arrays) {
            output.write(array);
        }
        return output.toByteArray();
    }

    private static final class BitWriter {
        private final ByteArrayOutputStream output = new ByteArrayOutputStream();
        private int bits;
        private int bitCount;

        void writeDcDifference(int difference) {
            if (difference == 0) {
                writeBit(0); // Huffman code 0, category 0.
            }
            else if (difference == 1 || difference == -1) {
                writeBit(1); // Huffman code 1, category 1.
                writeBit(difference > 0 ? 1 : 0);
            }
            else {
                throw new IllegalArgumentException("Synthetic stream only supports DC differences -1, 0, and 1");
            }
        }

        void writeBit(int bit) {
            bits = (bits << 1) | (bit & 1);
            bitCount++;
            if (bitCount == 8) {
                output.write(bits);
                bits = 0;
                bitCount = 0;
            }
        }

        byte[] toByteArray() throws IOException {
            if (bitCount > 0) {
                output.write(bits << (8 - bitCount));
                bits = 0;
                bitCount = 0;
            }
            // Decoder may fill its bit buffer eagerly. A zero pad byte keeps synthetic
            // streams byte-aligned without introducing extra samples.
            output.write(0);
            return output.toByteArray();
        }
    }
}

