    private PCXImageReader reader(Path file) throws IOException {
        return reader(new FileImageInputStream(file.toFile()));
    }

    private PCXImageReader reader(byte[] data) throws IOException {
        return reader(new MemoryCacheImageInputStream(new ByteArrayInputStream(data)));
    }

    private PCXImageReader reader(ImageInputStream input) throws IOException {
        inputs.add(input);

        PCXImageReader reader = new PCXImageReader(provider);
        reader.setInput(input);
        readers.add(reader);

        return reader;
    }

    private static byte[] buildHeader(int width, int height, int version, int compression,
                                      int bitsPerPixel, int channels, int bytesPerLine,
                                      byte[] egaPalette) {
        ByteArrayOutputStream out = new ByteArrayOutputStream(HEADER_SIZE);

        out.write(PCX.MAGIC);
        out.write(version);
        out.write(compression);
        out.write(bitsPerPixel);
        writeShortLE(out, 0);
        writeShortLE(out, 0);
        writeShortLE(out, width - 1);
        writeShortLE(out, height - 1);
        writeShortLE(out, 72);
        writeShortLE(out, 72);
        out.write(egaPalette, 0, egaPalette.length);
        out.write(0);
        out.write(channels);
        writeShortLE(out, bytesPerLine);
        writeShortLE(out, PCX.PALETTEINFO_COLOR);
        writeShortLE(out, 640);
        writeShortLE(out, 480);
        out.write(new byte[54], 0, 54);

        if (out.size() != HEADER_SIZE) {
            throw new AssertionError("Invalid synthetic header size: " + out.size());
        }

        return out.toByteArray();
    }

    private static void writeShortLE(ByteArrayOutputStream out, int value) {
        out.write(value & 0xFF);
        out.write((value >>> 8) & 0xFF);
    }

    private static byte[] encodeRle(byte[] raw) {
        ByteArrayOutputStream out = new ByteArrayOutputStream(raw.length);

        for (int i = 0; i < raw.length;) {
            int run = 1;
            while (i + run < raw.length && run < 63 && raw[i + run] == raw[i]) {
                run++;
            }

            int value = raw[i] & 0xFF;
            if (run > 1 || value >= 0xC0) {
                out.write(0xC0 | run);
                out.write(value);
            }
            else {
                out.write(value);
            }

            i += run;
        }

        return out.toByteArray();
    }

    private static int[] samples(BufferedImage image, int y) {
        int[] samples = new int[image.getWidth()];
        for (int x = 0; x < samples.length; x++) {
            samples[x] = image.getRaster().getSample(x, y, 0);
        }
        return samples;
    }

    private static List<ImageTypeSpecifier> collect(Iterator<ImageTypeSpecifier> iterator) {
        List<ImageTypeSpecifier> result = new ArrayList<>();
        while (iterator.hasNext()) {
            result.add(iterator.next());
        }
        return result;
    }

    private static String valueOf(Node root, String elementName) {
        Element element = findElement(root, elementName);
        assertNotNull(element, "Missing metadata element: " + elementName);
        return element.getAttribute("value");
    }

    private static Element findElement(Node node, String elementName) {
        if (node.getNodeType() == Node.ELEMENT_NODE && elementName.equals(node.getNodeName())) {
            return (Element) node;
        }

        for (Node child = node.getFirstChild(); child != null; child = child.getNextSibling()) {
            Element result = findElement(child, elementName);
            if (result != null) {
                return result;
            }
        }

        return null;
    }

    private static PcxFile pcx(int width, int height, int bitsPerPixel, int channels, int bytesPerLine) {
        return new PcxFile(width, height, bitsPerPixel, channels, bytesPerLine);
    }

    private static final class PcxFile {
        private final int width;
        private final int height;
        private final int bitsPerPixel;
        private final int channels;
        private final int bytesPerLine;
        private final byte[] egaPalette = new byte[48];

        private int version = PCX.VERSION_3;
        private int compression = PCX.COMPRESSION_RLE;
        private byte[] imageData = new byte[0];
        private byte[] vgaPalette;
        private byte[] trailer;

        private PcxFile(int width, int height, int bitsPerPixel, int channels, int bytesPerLine) {
            this.width = width;
            this.height = height;
            this.bitsPerPixel = bitsPerPixel;
            this.channels = channels;
            this.bytesPerLine = bytesPerLine;
        }

        private PcxFile egaColor(int index, int red, int green, int blue) {
            egaPalette[index * 3] = (byte) red;
            egaPalette[index * 3 + 1] = (byte) green;
            egaPalette[index * 3 + 2] = (byte) blue;
            return this;
        }

        private PcxFile vgaColor(int index, int red, int green, int blue) {
            if (vgaPalette == null) {
                vgaPalette = new byte[VGA_PALETTE_SIZE];
            }
            vgaPalette[index * 3] = (byte) red;
            vgaPalette[index * 3 + 1] = (byte) green;
            vgaPalette[index * 3 + 2] = (byte) blue;
            return this;
        }

        private PcxFile compressed(int compression) {
            this.compression = compression;
            return this;
        }

        private PcxFile uncompressed(int... raw) {
            this.compression = PCX.COMPRESSION_NONE;
            this.imageData = toBytes(raw);
            return this;
        }

        private PcxFile rle(int... raw) {
            this.compression = PCX.COMPRESSION_RLE;
            this.imageData = encodeRle(toBytes(raw));
            return this;
        }

        private PcxFile trailer(byte[] trailer) {
            this.trailer = trailer;
            return this;
        }

        private byte[] build() {
            if (vgaPalette != null && trailer != null) {
                throw new IllegalStateException("Use either a VGA palette or an explicit trailer");
            }

            ByteArrayOutputStream out = new ByteArrayOutputStream();
            out.write(buildHeader(width, height, version, compression, bitsPerPixel, channels, bytesPerLine, egaPalette), 0, HEADER_SIZE);
            out.write(imageData, 0, imageData.length);

            if (vgaPalette != null) {
                out.write(PCX.VGA_PALETTE_MAGIC);
                out.write(vgaPalette, 0, vgaPalette.length);
            }
            else if (trailer != null) {
                out.write(trailer, 0, trailer.length);
            }

            return out.toByteArray();
        }

        private static byte[] toBytes(int... values) {
            byte[] result = new byte[values.length];
            for (int i = 0; i < values.length; i++) {
                result[i] = (byte) values[i];
            }
            return result;
        }
    }
