    private PSDImageReader open(byte[] data) throws IOException {
        PSDImageReader reader = new PSDImageReader(new PSDImageReaderSpi());
        ImageInputStream input = ImageIO.createImageInputStream(new ByteArrayInputStream(data));
        assertNotNull(input);
        openResources.add(input);
        reader.setInput(input);
        return reader;
    }

    private ImageInputStream input(String resource) throws IOException {
        URL url = PSDImageReaderTests.class.getResource(resource);
        assertNotNull(url, "Missing test resource: " + resource);

        try {
            ImageInputStream input = ImageIO.createImageInputStream(new File(url.toURI()));
            assertNotNull(input, "Could not open test resource: " + resource);
            openResources.add(input);
            return input;
        }
        catch (URISyntaxException e) {
            throw new IOException("Invalid test resource URL: " + url, e);
        }
    }

