        byte[] rows = bytes(
                1, 10, 20, // one literal row: 10, 20
                1, 30, 40  // one literal row: 30, 40
        );
        byte[] imageData = concat(
                bytes(0, PSD.COMPRESSION_RLE),
                bytes(0, 3, 0, 3), // per-row byte counts
                rows
        );
        PSDImageReader reader = open(createPsd(1, 2, 2, 8, PSD.COLOR_MODE_GRAYSCALE, bytes(), imageData));

        IIOMetadata metadata = reader.getImageMetadata(0);
        Element compression = findElement(metadata.getAsTree(IIOMetadataFormatImpl.standardMetadataFormatName), "Compression");
        Element compressionName = findElement(compression, "CompressionTypeName");
        assertEquals("PackBits", compressionName.getAttribute("value"));
        assertNotNull(findElement(compression, "Lossless"));

        BufferedImage image = reader.read(0, null);
        assertAll(
                () -> assertEquals(10, image.getRaster().getSample(0, 0, 0)),
                () -> assertEquals(20, image.getRaster().getSample(1, 0, 0)),
                () -> assertEquals(30, image.getRaster().getSample(0, 1, 0)),
                () -> assertEquals(40, image.getRaster().getSample(1, 1, 0))
        );
    }

    @Test
    void readsMonochromeBitmapIntoBinaryImage() throws IOException {
        // One-bit rows, padded to bytes. The reader inverts to Java's binary convention.
        byte[] imageData = imageData(PSD.COMPRESSION_NONE, bytes(0xaa, 0x55));
        PSDImageReader reader = open(createPsd(1, 8, 2, 1, PSD.COLOR_MODE_BITMAP, bytes(), imageData));

        ImageTypeSpecifier rawType = reader.getRawImageType(0);
        assertEquals(BufferedImage.TYPE_BYTE_BINARY, rawType.getBufferedImageType());
        assertEquals(1, rawType.getNumBands());
        assertEquals(1, rawType.getBitsPerBand(0));

        BufferedImage image = reader.read(0, null);
        assertEquals(BufferedImage.TYPE_BYTE_BINARY, image.getType());
        assertArrayEquals(new int[] {0, 1, 0, 1, 0, 1, 0, 1},
                rowSamples(image, 0));
        assertArrayEquals(new int[] {1, 0, 1, 0, 1, 0, 1, 0},
                rowSamples(image, 1));
    }

