    @Test
    void exposesNativeAndStandardImageMetadata() throws IOException {
        PSDImageReader reader = open(TEST_ORIGINAL);

        IIOMetadata metadata = reader.getImageMetadata(0);
        assertNotNull(metadata);
        assertEquals(PSDMetadata.NATIVE_METADATA_FORMAT_NAME, metadata.getNativeMetadataFormatName());
        assertTrue(metadata.isStandardMetadataFormatSupported());

        Node nativeTree = metadata.getAsTree(PSDMetadata.NATIVE_METADATA_FORMAT_NAME);
        assertEquals(PSDMetadata.NATIVE_METADATA_FORMAT_NAME, nativeTree.getNodeName());
        Element header = findElement(nativeTree, "Header");
        assertAll(
                () -> assertEquals("PSD", header.getAttribute("type")),
                () -> assertEquals("1", header.getAttribute("version")),
                () -> assertEquals("3", header.getAttribute("channels")),
                () -> assertEquals("710", header.getAttribute("width")),
                () -> assertEquals("512", header.getAttribute("height")),
                () -> assertEquals("8", header.getAttribute("bits")),
                () -> assertEquals("RGB", header.getAttribute("mode"))
        );

        Node standardTree = metadata.getAsTree(IIOMetadataFormatImpl.standardMetadataFormatName);
        Element chroma = findElement(standardTree, "Chroma");
        Element colorSpaceType = findElement(chroma, "ColorSpaceType");
        Element compression = findElement(standardTree, "Compression");
        Element compressionName = findElement(compression, "CompressionTypeName");
        Element document = findElement(standardTree, "Document");
        Element formatVersion = findElement(document, "FormatVersion");
        Element transparency = findElement(standardTree, "Transparency");
        Element alpha = findElement(transparency, "Alpha");

        assertAll(
                () -> assertEquals("RGB", colorSpaceType.getAttribute("name")),
                () -> assertEquals("3", findElement(chroma, "NumChannels").getAttribute("value")),
                () -> assertEquals("PackBits", compressionName.getAttribute("value")),
                () -> assertEquals("1", formatVersion.getAttribute("value")),
                () -> assertEquals("none", alpha.getAttribute("value"))
        );
    }

