    private PSDImageReader open(String resource) throws IOException {
        PSDImageReader reader = new PSDImageReader(new PSDImageReaderSpi());
        reader.setInput(input(resource));
        return reader;
    }

    private PSDImageReader open(byte[] data) throws IOException {
        PSDImageReader reader = new PSDImageReader(new PSDImageReaderSpi());
        ImageInputStream input = ImageIO.createImageInputStream(new ByteArrayInputStream(data));
        assertNotNull(input);
        openResources.add(input);
        reader.setInput(input);
        return reader;
    }

    private ImageInputStream input(String resource) throws IOException {
        URL url = PSDImageReaderTests.class.getResource(resource);
        assertNotNull(url, "Missing test resource: " + resource);

        try {
            ImageInputStream input = ImageIO.createImageInputStream(new File(url.toURI()));
            assertNotNull(input, "Could not open test resource: " + resource);
            openResources.add(input);
            return input;
        }
        catch (URISyntaxException e) {
            throw new IOException("Invalid test resource URL: " + url, e);
        }
    }

    private void assertHeaderRejected(byte[] header, String expectedMessagePart) {
        try {
            PSDImageReader reader = open(header);
            IOException exception = assertThrows(IOException.class, () -> reader.getWidth(0));
            assertTrue(exception.getMessage().contains(expectedMessagePart), exception.toString());
        }
        catch (IOException e) {
            throw new AssertionError("Could not open synthetic input", e);
        }
    }

    private static byte[] createPsd(int channels, int width, int height, int bits, int mode,
                                    byte[] colorModeData, byte[] imageData) throws IOException {
        return createPsd(PSD.VERSION_PSD, channels, width, height, bits, mode, colorModeData, imageData);
    }

    private static byte[] createPsd(int version, int channels, int width, int height, int bits, int mode,
                                    byte[] colorModeData, byte[] imageData) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        DataOutputStream data = new DataOutputStream(output);

        data.writeInt(PSD.SIGNATURE_8BPS);
        data.writeShort(version);
        data.write(new byte[6]);
        data.writeShort(channels);
        data.writeInt(height);
        data.writeInt(width);
        data.writeShort(bits);
        data.writeShort(mode);

        data.writeInt(colorModeData.length);
        data.write(colorModeData);

        // Empty image resource section.
        data.writeInt(0);

        // Empty layer and mask information section. PSB uses a 64-bit length here.
        if (version == PSD.VERSION_PSB) {
            data.writeLong(0);
        }
        else {
            data.writeInt(0);
        }

        data.write(imageData);
        data.flush();

        return output.toByteArray();
    }

    private static byte[] header(String signature, int version, int channels, int width, int height,
                                 int bits, int mode) {
        try {
            ByteArrayOutputStream output = new ByteArrayOutputStream();
            DataOutputStream data = new DataOutputStream(output);

            data.write(signature.getBytes(StandardCharsets.US_ASCII));
            data.writeShort(version);
            data.write(new byte[6]);
            data.writeShort(channels);
            data.writeInt(height);
            data.writeInt(width);
            data.writeShort(bits);
            data.writeShort(mode);
            data.flush();

            return output.toByteArray();
        }
        catch (IOException e) {
            throw new AssertionError(e);
        }
    }

    private static byte[] imageData(int compression, byte[] data) {
        return concat(new byte[] {(byte) (compression >>> 8), (byte) compression}, data);
    }

    private static byte[] bytes(int... values) {
        byte[] bytes = new byte[values.length];
        for (int i = 0; i < values.length; i++) {
            bytes[i] = (byte) values[i];
        }
        return bytes;
    }

    private static byte[] concat(byte[]... parts) {
        int length = 0;
        for (byte[] part : parts) {
            length += part.length;
        }

        byte[] result = new byte[length];
        int offset = 0;
        for (byte[] part : parts) {
            System.arraycopy(part, 0, result, offset, part.length);
            offset += part.length;
        }
        return result;
    }

    private static int[] rowSamples(BufferedImage image, int y) {
        int[] samples = new int[image.getWidth()];
        for (int x = 0; x < samples.length; x++) {
            samples[x] = image.getRaster().getSample(x, y, 0);
        }
        return samples;
    }

    private static List<ImageTypeSpecifier> toList(Iterator<ImageTypeSpecifier> iterator) {
        List<ImageTypeSpecifier> types = new ArrayList<>();
        while (iterator.hasNext()) {
            types.add(iterator.next());
        }
        return types;
    }

    private static Element findElement(Node node, String name) {
        if (node.getNodeType() == Node.ELEMENT_NODE && name.equals(node.getNodeName())) {
            return (Element) node;
        }

        for (Node child = node.getFirstChild(); child != null; child = child.getNextSibling()) {
            Element found = findElement(child, name);
            if (found != null) {
                return found;
            }
        }

        return null;
    }

    private static Element findElementWithAttribute(Node node, String elementName, String attribute, String value) {
        if (node.getNodeType() == Node.ELEMENT_NODE && elementName.equals(node.getNodeName())) {
            Element element = (Element) node;
            if (value.equals(element.getAttribute(attribute))) {
                return element;
            }
        }

        for (Node child = node.getFirstChild(); child != null; child = child.getNextSibling()) {
            Element found = findElementWithAttribute(child, elementName, attribute, value);
            if (found != null) {
                return found;
            }
        }

        return null;
    }

    private static List<Element> childrenNamed(Node node, String name) {
        List<Element> children = new ArrayList<>();
        NodeList nodes = node.getChildNodes();
        for (int i = 0; i < nodes.getLength(); i++) {
            Node child = nodes.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE && name.equals(child.getNodeName())) {
                children.add((Element) child);
            }
        }
        return children;
    }
