    @Test
    void exposesRgbImageMetadataTypesAndExactPixels() throws IOException {
        byte[] rgb = rgbBytes(
                0xFF0000, 0x00FF00, 0x0000FF,
                0xFFFFFF, 0x000000, 0xFFFF00);
        byte[] tiff = new TiffBuilder()
                .startImage(3, 2, 8, 3, TIFFBaseline.PHOTOMETRIC_RGB)
                .stripData(rgb)
                .endImage()
                .build();

        reader = createReader(tiff);

        assertEquals(1, reader.getNumImages(false));
        assertEquals(1, reader.getNumImages(true));
        assertEquals(3, reader.getWidth(0));
        assertEquals(2, reader.getHeight(0));
        assertTrue(reader.canReadRaster());
        assertFalse(reader.isImageTiled(0));
        assertEquals(3, reader.getTileWidth(0));
        assertEquals(2, reader.getTileHeight(0));

        ImageTypeSpecifier rawType = reader.getRawImageType(0);
        assertEquals(3, rawType.getNumBands());
        assertEquals(8, rawType.getBitsPerBand(0));
        assertEquals(DataBuffer.TYPE_BYTE, rawType.getSampleModel().getTransferType());
        assertEquals(ColorSpace.TYPE_RGB, rawType.getColorModel().getColorSpace().getType());

        Iterator<ImageTypeSpecifier> imageTypes = reader.getImageTypes(0);
        assertTrue(imageTypes.hasNext());
        ImageTypeSpecifier firstType = imageTypes.next();
        assertEquals(BufferedImage.TYPE_3BYTE_BGR, firstType.getBufferedImageType());
        assertTrue(imageTypes.hasNext());
        assertEquals(rawType, imageTypes.next());
