    private static void assertRgb(BufferedImage image, int x, int y, int expectedRgb) {
        assertEquals(expectedRgb, image.getRGB(x, y) & 0xFFFFFF,
                "Unexpected RGB value at " + x + "," + y);
    }

    private static void assertArrayEquals(int[] expected, int[] actual) {
        assertEquals(Arrays.toString(expected), Arrays.toString(actual));
    }

    private static byte[] rgbBytes(int... rgb) {
        byte[] result = new byte[rgb.length * 3];
        for (int i = 0; i < rgb.length; i++) {
            result[i * 3] = (byte) (rgb[i] >>> 16);
            result[i * 3 + 1] = (byte) (rgb[i] >>> 8);
            result[i * 3 + 2] = (byte) rgb[i];
        }
        return result;
    }

    private static byte[] shorts(ByteOrder order, int... values) {
        ByteBuffer buffer = ByteBuffer.allocate(values.length * 2).order(order);
        for (int value : values) {
            buffer.putShort((short) value);
        }
        return buffer.array();
    }

    private static final class Blob {
        final byte[] data;
        long offset;

        Blob(byte[] data) {
            this.data = data.clone();
        }
    }

    private static final class TagValue {
        final int tag;
        final int type;
        final long[] values;
        final List<Blob> blobs;

        TagValue(int tag, int type, long[] values, List<Blob> blobs) {
            this.tag = tag;
            this.type = type;
            this.values = values;
            this.blobs = blobs;
        }

        int count() {
            return blobs != null ? blobs.size() : values.length;
        }

        int size() {
            return count() * typeSize(type);
        }

        byte[] bytes(ByteOrder order) {
            ByteBuffer buffer = ByteBuffer.allocate(size()).order(order);
            if (blobs != null) {
                for (Blob blob : blobs) {
                    buffer.putInt((int) blob.offset);
                }
            }
            else {
                for (long value : values) {
                    switch (type) {
                        case TIFF.TYPE_BYTE:
                        case TIFF.TYPE_UNDEFINED:
                            buffer.put((byte) value);
                            break;
                        case TIFF.TYPE_SHORT:
                            buffer.putShort((short) value);
                            break;
                        case TIFF.TYPE_LONG:
                            buffer.putInt((int) value);
                            break;
                        default:
                            throw new AssertionError("Unsupported test TIFF type: " + type);
                    }
                }
            }
            return buffer.array();
        }
    }

    private static int typeSize(int type) {
        switch (type) {
            case TIFF.TYPE_BYTE:
            case TIFF.TYPE_UNDEFINED:
                return 1;
            case TIFF.TYPE_SHORT:
                return 2;
            case TIFF.TYPE_LONG:
                return 4;
            default:
                throw new AssertionError("Unsupported test TIFF type: " + type);
        }
    }

    private static final class ImageBuilder {
        private final TiffBuilder owner;
        private final List<TagValue> tags = new ArrayList<>();
        private final List<Blob> blobs = new ArrayList<>();

        ImageBuilder(TiffBuilder owner) {
            this.owner = owner;
        }

        TiffBuilder endImage() {
            return owner.endImage();
        }

        ImageBuilder tag(int tag, int type, long... values) {
            removeTag(tag);
            tags.add(new TagValue(tag, type, values.clone(), null));
            return this;
        }

        ImageBuilder removeTag(int tag) {
            tags.removeIf(value -> value.tag == tag);
            return this;
        }

        ImageBuilder stripData(byte[]... strips) {
            List<Blob> stripBlobs = addBlobs(strips);
            tagBlobs(TIFF.TAG_STRIP_OFFSETS, stripBlobs);
            long[] counts = new long[strips.length];
            for (int i = 0; i < strips.length; i++) {
                counts[i] = strips[i].length;
            }
            return tag(TIFF.TAG_STRIP_BYTE_COUNTS, TIFF.TYPE_LONG, counts);
        }

        ImageBuilder tileData(byte[]... tiles) {
            List<Blob> tileBlobs = addBlobs(tiles);
            tagBlobs(TIFF.TAG_TILE_OFFSETS, tileBlobs);
            long[] counts = new long[tiles.length];
            for (int i = 0; i < tiles.length; i++) {
                counts[i] = tiles[i].length;
            }
            return tag(TIFF.TAG_TILE_BYTE_COUNTS, TIFF.TYPE_LONG, counts);
        }

        private List<Blob> addBlobs(byte[][] data) {
            List<Blob> result = new ArrayList<>(data.length);
            for (byte[] item : data) {
                Blob blob = new Blob(item);
                blobs.add(blob);
                result.add(blob);
            }
            return result;
        }

        private void tagBlobs(int tag, List<Blob> values) {
            removeTag(tag);
            tags.add(new TagValue(tag, TIFF.TYPE_LONG, null, new ArrayList<>(values)));
        }
    }

    private static final class TiffBuilder {
        private final ByteOrder order;
        private final List<ImageBuilder> images = new ArrayList<>();
        private ImageBuilder current;

        TiffBuilder() {
            this(ByteOrder.LITTLE_ENDIAN);
        }

        TiffBuilder(ByteOrder order) {
            this.order = order;
        }

        ImageBuilder startImage(int width, int height, int bitsPerSample, int samplesPerPixel, int photometricInterpretation) {
            if (current != null) {
                throw new IllegalStateException("Previous image was not ended");
            }
            current = new ImageBuilder(this);
            images.add(current);
            current.tag(TIFF.TAG_IMAGE_WIDTH, TIFF.TYPE_LONG, width)
                    .tag(TIFF.TAG_IMAGE_HEIGHT, TIFF.TYPE_LONG, height)
                    .tag(TIFF.TAG_BITS_PER_SAMPLE, TIFF.TYPE_SHORT, repeat(bitsPerSample, samplesPerPixel))
                    .tag(TIFF.TAG_COMPRESSION, TIFF.TYPE_SHORT, TIFFBaseline.COMPRESSION_NONE)
                    .tag(TIFF.TAG_PHOTOMETRIC_INTERPRETATION, TIFF.TYPE_SHORT, photometricInterpretation)
                    .tag(TIFF.TAG_SAMPLES_PER_PIXEL, TIFF.TYPE_SHORT, samplesPerPixel)
                    .tag(TIFF.TAG_ROWS_PER_STRIP, TIFF.TYPE_LONG, height);
            return current;
        }

        TiffBuilder endImage() {
            if (current == null) {
                throw new IllegalStateException("No image in progress");
            }
            current = null;
            return this;
        }

        byte[] build() {
            if (current != null) {
                throw new IllegalStateException("Image not ended");
            }
            if (images.isEmpty()) {
                throw new IllegalStateException("No images");
            }

            int imageCount = images.size();
            long[] ifdOffsets = new long[imageCount];
            long cursor = 8;
            for (int i = 0; i < imageCount; i++) {
                ifdOffsets[i] = cursor;
                ImageBuilder image = images.get(i);
                cursor += ifdSize(image);
            }

            cursor = align2(cursor);
            for (ImageBuilder image : images) {
                for (Blob blob : image.blobs) {
                    blob.offset = cursor;
                    cursor += blob.data.length;
                    cursor = align2(cursor);
                }
            }

            ByteBuffer buffer = ByteBuffer.allocate((int) cursor).order(order);
            if (order == ByteOrder.LITTLE_ENDIAN) {
                buffer.put((byte) 'I').put((byte) 'I');
            }
            else {
                buffer.put((byte) 'M').put((byte) 'M');
            }
            buffer.putShort((short) TIFF.TIFF_MAGIC);
            buffer.putInt((int) ifdOffsets[0]);

            for (int i = 0; i < imageCount; i++) {
                ImageBuilder image = images.get(i);
                List<TagValue> sortedTags = new ArrayList<>(image.tags);
                sortedTags.sort(Comparator.comparingInt(value -> value.tag));

                buffer.position((int) ifdOffsets[i]);
                buffer.putShort((short) sortedTags.size());

                long externalPosition = ifdOffsets[i] + 2 + sortedTags.size() * 12L + 4;
                List<Long> externalOffsets = new LinkedList<>();
                for (TagValue tag : sortedTags) {
                    byte[] data = tag.bytes(order);
                    buffer.putShort((short) tag.tag);
                    buffer.putShort((short) tag.type);
                    buffer.putInt(tag.count());
                    if (data.length <= 4) {
                        buffer.put(data);
                        for (int pad = data.length; pad < 4; pad++) {
                            buffer.put((byte) 0);
                        }
                    }
                    else {
                        buffer.putInt((int) externalPosition);
                        externalOffsets.add(externalPosition);
                        externalPosition += align2(data.length);
                    }
                }

                buffer.putInt(i + 1 < imageCount ? (int) ifdOffsets[i + 1] : 0);

                long position = ifdOffsets[i] + 2 + sortedTags.size() * 12L + 4;
                int externalIndex = 0;
                for (TagValue tag : sortedTags) {
                    byte[] data = tag.bytes(order);
                    if (data.length > 4) {
                        buffer.position((int) position);
                        buffer.put(data);
                        position += align2(data.length);
                        externalIndex++;
                    }
                }
                assertEquals(externalOffsets.size(), externalIndex);
            }

            for (ImageBuilder image : images) {
                for (Blob blob : image.blobs) {
                    buffer.position((int) blob.offset);
                    buffer.put(blob.data);
                }
            }

            return buffer.array();
        }

        private static long ifdSize(ImageBuilder image) {
            long size = 2 + image.tags.size() * 12L + 4;
            for (TagValue tag : image.tags) {
                int tagSize = tag.size();
                if (tagSize > 4) {
                    size += align2(tagSize);
                }
            }
            return size;
        }

        private static long align2(long value) {
            return (value + 1) & ~1L;
        }
    }

    private static long[] repeat(long value, int count) {
        long[] result = new long[count];
        Arrays.fill(result, value);
        return result;
    }
}

