        cmbSnap.assertPlaneChanged(cmb, U, "chroma U");
        cmbSnap.assertPlaneChanged(cmb, V, "chroma V");
        cmbSnap.assertPlaneUnchanged(cmb, Y2, "Y2");
        lmbSnap.assertPlaneChanged(lmb, Y1, "neighbour luma");

