    // --- helpers ---------------------------------------------------------------

    private static MacroBlock macroBlock(int value) {
        MacroBlock mb = new MacroBlock(0, 0, true);
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                mb.getSubBlock(Y1, x, y).setDest(uniform(value));
            }
        }
        for (int x = 0; x < 2; x++) {
            for (int y = 0; y < 2; y++) {
                mb.getSubBlock(U, x, y).setDest(uniform(value));
                mb.getSubBlock(V, x, y).setDest(uniform(value));
            }
        }
        mb.getY2SubBlock().setDest(uniform(value));
        return mb;
    }

    private static int[][] uniform(int value) {
        return rows(value, value, value, value);
    }

    private static int[][] rows(int r0, int r1, int r2, int r3) {
        return new int[][] {
                {r0, r0, r0, r0},
                {r1, r1, r1, r1},
                {r2, r2, r2, r2},
                {r3, r3, r3, r3}
        };
    }

    private static void setRows(SubBlock sb, int r0, int r1, int r2, int r3) {
        sb.setDest(rows(r0, r1, r2, r3));
    }

    private static int[][] copy(int[][] source) {
        int[][] result = new int[source.length][];
        for (int i = 0; i < source.length; i++) {
            result[i] = source[i].clone();
        }
        return result;
    }

    private static void setSkipInnerLoopFilter(MacroBlock mb, boolean value) throws Exception {
        Field field = MacroBlock.class.getDeclaredField("skipInnerLoopFilter");
        field.setAccessible(true);
        field.setBoolean(mb, value);
    }

    private static int planeColumns(SubBlock.Plane plane) {
        switch (plane) {
            case Y1:
                return 4;
            case U:
            case V:
                return 2;
            default:
                return 1;
        }
    }

    private static SubBlock subBlock(MacroBlock mb, SubBlock.Plane plane, int x, int y) {
        return plane == Y2 ? mb.getY2SubBlock() : mb.getSubBlock(plane, x, y);
    }

    /** Largest |P0 - Q0| over the left macro block edge of the given plane. */
    private static int edgeGap(MacroBlock cmb, MacroBlock lmb, SubBlock.Plane plane) {
        int last = planeColumns(plane) - 1;
        int gap = 0;
        for (int y = 0; y < planeColumns(plane); y++) {
            int p0 = subBlock(lmb, plane, last, y).getDest()[3][0];
            int q0 = subBlock(cmb, plane, 0, y).getDest()[0][0];
            gap = Math.max(gap, Math.abs(p0 - q0));
        }
        return gap;
    }

    private static void assertPixels(String message, int[][] expected, int[][] actual) {
        for (int r = 0; r < expected.length; r++) {
            for (int c = 0; c < expected[r].length; c++) {
                assertEquals(expected[r][c], actual[r][c], message + " at [" + r + "][" + c + "]");
            }
        }
    }

    private static void assertPlaneInRange(MacroBlock mb) {
        for (SubBlock.Plane plane : new SubBlock.Plane[] {Y1, U, V, Y2}) {
            int columns = planeColumns(plane);
            for (int x = 0; x < columns; x++) {
                for (int y = 0; y < columns; y++) {
                    int[][] dest = subBlock(mb, plane, x, y).getDest();
                    for (int[] row : dest) {
                        for (int value : row) {
                            assertTrue(value >= 0 && value <= 255,
                                    plane + "[" + x + "," + y + "] out of range: " + value);
                        }
                    }
                }
            }
        }
    }

    /** Snapshot of all sample arrays of a macro block, used for change detection. */
    private static final class Snap {
        private final int[][][][] planes = new int[SubBlock.Plane.values().length][][][];

        Snap(MacroBlock mb) {
            for (SubBlock.Plane plane : SubBlock.Plane.values()) {
                int columns = planeColumns(plane);
                int[][][] blocks = new int[columns * columns][][];
                for (int x = 0; x < columns; x++) {
                    for (int y = 0; y < columns; y++) {
                        blocks[x * columns + y] = copy(subBlock(mb, plane, x, y).getDest());
                    }
                }
                planes[plane.ordinal()] = blocks;
            }
        }

        void assertUnchanged(MacroBlock mb, String description) {
            for (SubBlock.Plane plane : SubBlock.Plane.values()) {
                assertPlaneUnchanged(mb, plane, description);
            }
        }

        void assertPlaneUnchanged(MacroBlock mb, SubBlock.Plane plane, String description) {
            assertEquals(0, differences(mb, plane), description + ": " + plane + " plane must not be modified");
        }

        void assertPlaneChanged(MacroBlock mb, SubBlock.Plane plane, String description) {
            int differences = differences(mb, plane);
            assertTrue(differences > 0, description + ": " + plane + " plane was expected to be modified");
        }

        private int differences(MacroBlock mb, SubBlock.Plane plane) {
            int columns = planeColumns(plane);
            int[][][] before = planes[plane.ordinal()];
            int changed = 0;
            for (int x = 0; x < columns; x++) {
                for (int y = 0; y < columns; y++) {
                    int[][] expected = before[x * columns + y];
                    int[][] actual = subBlock(mb, plane, x, y).getDest();
                    for (int r = 0; r < expected.length; r++) {
                        for (int c = 0; c < expected[r].length; c++) {
                            if (expected[r][c] != actual[r][c]) {
                                changed++;
                            }
                        }
                    }
                }
            }
            return changed;
        }
    }
}

