class LoopFilterTests {

    private static final int KEY_FRAME = 0;
    private static final int INTER_FRAME = 1;

    // --- loopFilterBlock: dispatching -----------------------------------------

    @Test
    void noFilteringAtAllWhenFilterLevelIsZero() {
        MacroBlock cmb = macroBlock(100);
        MacroBlock lmb = macroBlock(120);
        MacroBlock tmb = macroBlock(120);
        cmb.setFilterLevel(0);

        Snap cmbSnap = new Snap(cmb);
        Snap lmbSnap = new Snap(lmb);
        Snap tmbSnap = new Snap(tmb);

        LoopFilter.loopFilterBlock(cmb, lmb, tmb, KEY_FRAME, false, 0);
