                assertFalse(sb.hasRecon());
                assertFalse(sb.isDest());

                if (x == 0) {
                    assertNull(sb.getLeft());
                }
                else {
                    assertSame(mb.getYSubBlock(x - 1, y), sb.getLeft());
                }
                if (y == 0) {
                    assertNull(sb.getAbove());
                }
                else {
                    assertSame(mb.getYSubBlock(x, y - 1), sb.getAbove());
                }
            }
        }

        for (SubBlock.Plane plane : new SubBlock.Plane[]{SubBlock.Plane.U, SubBlock.Plane.V}) {
            for (int y = 0; y < 2; y++) {
                for (int x = 0; x < 2; x++) {
                    SubBlock sb = mb.getSubBlock(plane, x, y);
                    assertSame(mb, sb.getMacroBlock());
                    assertEquals(plane, sb.getPlane());
                    if (x == 0) {
                        assertNull(sb.getLeft());
                    }
                    else {
                        assertSame(mb.getSubBlock(plane, x - 1, y), sb.getLeft());
                    }
                    if (y == 0) {
                        assertNull(sb.getAbove());
                    }
                    else {
                        assertSame(mb.getSubBlock(plane, x, y - 1), sb.getAbove());
                    }
                }
            }
        }

        assertSame(mb.y2SubBlock, mb.getY2SubBlock());
        assertEquals(SubBlock.Plane.Y2, mb.getY2SubBlock().getPlane());
        assertNull(mb.getY2SubBlock().getAbove());
        assertNull(mb.getY2SubBlock().getLeft());
    }

