    @Test
    void dequantMacroBlockPropagatesY2DcThroughLumaBlocks() {
        FrameFixture fixture = fixture(0, 0, true);
        MacroBlock mb = fixture.target;
        mb.setYMode(Globals.DC_PRED);
        mb.setUvMode(Globals.DC_PRED);
        mb.setSegmentId(0);

        SegmentQuant quant = fixture.frame.getSegmentQuants().getSegQuants()[0];
        quant.setQindex(0);
        quant.setY2dc(0);              // 4 * 2 = 8
        quant.setY2ac_delta_q(0);
        quant.setY1dc(0);
        quant.setUvdc_delta_q(0);
        quant.setUvac_delta_q(0);

        mb.getY2SubBlock().getTokens()[0] = 8;

        mb.dequantMacroBlock(fixture.frame);

        // Y2 coefficient 8 * dc-quant 8 = 64, whose inverse Walsh transform is
        // a flat 8. That DC term is added to every luma block (8 / 8 = 1).
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertTrue(mb.getYSubBlock(x, y).hasRecon());
                assertMatrixEquals(filled(129), mb.getYSubBlock(x, y).getRecon());
            }
        }
        for (int y = 0; y < 2; y++) {
            for (int x = 0; x < 2; x++) {
                assertTrue(mb.getUSubBlock(x, y).hasRecon());
                assertTrue(mb.getVSubBlock(x, y).hasRecon());
                assertMatrixEquals(filled(128), mb.getUSubBlock(x, y).getRecon());
                assertMatrixEquals(filled(128), mb.getVSubBlock(x, y).getRecon());
            }
        }
    }

