    private static FrameFixture fixture(int mbX, int mbY, boolean keepDebugInfo) {
        try {
        byte[] data = new byte[2048];
        ImageInputStream frameStream = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));
        VP8Frame frame = new VP8Frame(frameStream, true);

        MacroBlock[] currentRow = new MacroBlock[mbX + 3];
        for (int col = 0; col < currentRow.length; col++) {
            currentRow[col] = new MacroBlock(col, mbY + 1, keepDebugInfo && col == mbX + 1);
        }
        MacroBlock[] previousRow = new MacroBlock[mbX + 3];
        for (int col = 0; col < previousRow.length; col++) {
            previousRow[col] = new MacroBlock(col, mbY, true);
        }

        setField(frame, "currentMacroBlockRow", currentRow);
        setField(frame, "previousMacroBlockRow", previousRow);
        setField(frame, "topMacroBlockRow", previousRow);
        setField(frame, "currentMacroBlockRowIndex", mbY);
        setField(frame, "macroBlockCols", mbX + 1);
        setField(frame, "macroBlockRows", mbY + 1);
        setField(frame, "lastNonBPredMacroBlockByColumn", previousRow.clone());
        setField(frame, "segmentQuants", new SegmentQuants());

        ImageInputStream tokenStream = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));
        setField(frame, "tokenBoolDecoder", new BoolDecoder(tokenStream, 0));

        return new FrameFixture(frame, currentRow[mbX + 1]);
        }
        catch (IOException e) {
            throw new AssertionError("Unable to create in-memory VP8 frame fixture", e);
        }
    }

    private static void setField(Object target, String name, Object value) {
        try {
            Field field = target.getClass().getDeclaredField(name);
            field.setAccessible(true);
            field.set(target, value);
        }
        catch (ReflectiveOperationException e) {
            throw new AssertionError("Unable to initialise test fixture field " + name, e);
        }
    }

    private static void fillMacroBlockRecon(MacroBlock macroBlock, SubBlock.Plane plane, int value) {
        int blocks = plane == SubBlock.Plane.Y1 ? 4 : 2;
        for (int y = 0; y < blocks; y++) {
            for (int x = 0; x < blocks; x++) {
                macroBlock.getSubBlock(plane, x, y).setDest(filled(value));
            }
        }
    }

    private static void assertAllYPixels(MacroBlock macroBlock, int expected) {
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertMatrixEquals(filled(expected), macroBlock.getYSubBlock(x, y).getPredict());
            }
        }
    }

    private static void assertAllUVPixels(MacroBlock macroBlock, int expectedU, int expectedV) {
        for (int y = 0; y < 2; y++) {
            for (int x = 0; x < 2; x++) {
                assertMatrixEquals(filled(expectedU), macroBlock.getUSubBlock(x, y).getPredict());
                assertMatrixEquals(filled(expectedV), macroBlock.getVSubBlock(x, y).getPredict());
            }
        }
    }

    private static int[][] filled(int value) {
        int[][] result = new int[4][4];
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                result[x][y] = value;
            }
        }
        return result;
    }

    private static int[][] copy(int[][] input) {
        int[][] result = new int[4][4];
        for (int y = 0; y < 4; y++) {
            System.arraycopy(input[y], 0, result[y], 0, 4);
        }
        return result;
    }

    private static void assertMatrixEquals(int[][] expected, int[][] actual) {
        assertNotNull(actual);
        for (int y = 0; y < 4; y++) {
            assertArrayEquals(expected[y], actual[y]);
        }
    }

    private static final class FrameFixture {
        private final VP8Frame frame;
        private final MacroBlock target;

        private FrameFixture(VP8Frame frame, MacroBlock target) {
            this.frame = frame;
            this.target = target;
        }
    }
