            assertMatrixEquals(filled(x == 0 ? 31 : 32), fixture.target.getUSubBlock(x, 1).getPredict());
            assertMatrixEquals(filled(x == 0 ? 131 : 132), fixture.target.getVSubBlock(x, 0).getPredict());
            assertMatrixEquals(filled(x == 0 ? 131 : 132), fixture.target.getVSubBlock(x, 1).getPredict());
        }
    }

    @Test
    void predictUVHorizontalCopiesTheMatchingLeftBlock() {
        FrameFixture fixture = fixture(1, 0, true);
        MacroBlock left = fixture.frame.getMacroBlock(0, 0);
        left.getUSubBlock(1, 0).setDest(filled(41));
        left.getUSubBlock(1, 1).setDest(filled(42));
        left.getVSubBlock(1, 0).setDest(filled(141));
        left.getVSubBlock(1, 1).setDest(filled(142));

        fixture.target.setUvMode(Globals.H_PRED);
        fixture.target.predictUV(fixture.frame);

        for (int y = 0; y < 2; y++) {
            assertMatrixEquals(filled(y == 0 ? 41 : 42), fixture.target.getUSubBlock(0, y).getPredict());
            assertMatrixEquals(filled(y == 0 ? 41 : 42), fixture.target.getUSubBlock(1, y).getPredict());
            assertMatrixEquals(filled(y == 0 ? 141 : 142), fixture.target.getVSubBlock(0, y).getPredict());
            assertMatrixEquals(filled(y == 0 ? 141 : 142), fixture.target.getVSubBlock(1, y).getPredict());
        }
    }

    @Test
    void predictUVTrueMotionCombinesAboveLeftAndCorner() {
        FrameFixture fixture = fixture(1, 1, true);
        fillMacroBlockRecon(fixture.frame.getMacroBlock(1, 0), SubBlock.Plane.U, 100);
        fillMacroBlockRecon(fixture.frame.getMacroBlock(1, 0), SubBlock.Plane.V, 200);
        fillMacroBlockRecon(fixture.frame.getMacroBlock(0, 1), SubBlock.Plane.U, 60);
        fillMacroBlockRecon(fixture.frame.getMacroBlock(0, 1), SubBlock.Plane.V, 110);
        fillMacroBlockRecon(fixture.frame.getMacroBlock(0, 0), SubBlock.Plane.U, 10);
        fillMacroBlockRecon(fixture.frame.getMacroBlock(0, 0), SubBlock.Plane.V, 20);

        fixture.target.setUvMode(Globals.TM_PRED);
        fixture.target.predictUV(fixture.frame);

        assertAllUVPixels(fixture.target, 150, 255);
    }

    @Test
    void predictUVRejectsUnsupportedMode() {
        FrameFixture fixture = fixture(0, 0, true);
        fixture.target.setUvMode(99);

        assertThrows(AssertionError.class, () -> fixture.target.predictUV(fixture.frame));
    }

    @Test
    void dequantMacroBlockPropagatesY2DcThroughLumaBlocks() {
        FrameFixture fixture = fixture(0, 0, true);
        MacroBlock mb = fixture.target;
        mb.setYMode(Globals.DC_PRED);
        mb.setUvMode(Globals.DC_PRED);
        mb.setSegmentId(0);

        SegmentQuant quant = fixture.frame.getSegmentQuants().getSegQuants()[0];
        quant.setQindex(0);
        quant.setY2dc(0);              // 4 * 2 = 8
        quant.setY2ac_delta_q(0);
        quant.setY1dc(0);
        quant.setUvdc_delta_q(0);
        quant.setUvac_delta_q(0);

        mb.getY2SubBlock().getTokens()[0] = 8;

        mb.dequantMacroBlock(fixture.frame);

        // Y2 coefficient 8 * dc-quant 8 = 64, whose inverse Walsh transform is
        // a flat 8. That DC term is added to every luma block (8 / 8 = 1).
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertTrue(mb.getYSubBlock(x, y).hasRecon());
                assertMatrixEquals(filled(129), mb.getYSubBlock(x, y).getRecon());
            }
        }
        for (int y = 0; y < 2; y++) {
            for (int x = 0; x < 2; x++) {
                assertTrue(mb.getUSubBlock(x, y).hasRecon());
                assertTrue(mb.getVSubBlock(x, y).hasRecon());
                assertMatrixEquals(filled(128), mb.getUSubBlock(x, y).getRecon());
                assertMatrixEquals(filled(128), mb.getVSubBlock(x, y).getRecon());
            }
        }
    }

    @Test
    void dequantMacroBlockBPredReconstructsEveryBlockThroughSubBlockPrediction() {
        FrameFixture fixture = fixture(0, 0, true);
        MacroBlock mb = fixture.target;
        mb.setYMode(Globals.B_PRED);
        mb.setUvMode(Globals.DC_PRED);
        mb.setSegmentId(0);

        // Keep the quantizers non-zero but use zero coefficients.
        SegmentQuant quant = fixture.frame.getSegmentQuants().getSegQuants()[0];
        quant.setQindex(0);
        quant.setY1dc(0);
        quant.setUvdc_delta_q(0);
        quant.setUvac_delta_q(0);

        // Give every intra-prediction edge a known 128 sample so all B_DC
        // predictions are deterministic.
        fillMacroBlockRecon(fixture.frame.getMacroBlock(0, -1), SubBlock.Plane.Y1, 128);
        fillMacroBlockRecon(fixture.frame.getMacroBlock(-1, 0), SubBlock.Plane.Y1, 128);

        mb.dequantMacroBlock(fixture.frame);

        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                SubBlock sb = mb.getYSubBlock(x, y);
                assertTrue(sb.hasRecon());
                assertMatrixEquals(filled(128), sb.getRecon());
            }
        }
        for (int y = 0; y < 2; y++) {
            for (int x = 0; x < 2; x++) {
                assertMatrixEquals(filled(128), mb.getUSubBlock(x, y).getRecon());
                assertMatrixEquals(filled(128), mb.getVSubBlock(x, y).getRecon());
            }
        }
    }

    @Test
    void dequantMacroBlockUsesY2DcWithSignAndClampsReconstruction() {
        FrameFixture fixture = fixture(0, 0, true);
        MacroBlock mb = fixture.target;
        mb.setYMode(Globals.DC_PRED);
        mb.setUvMode(Globals.DC_PRED);
        mb.setSegmentId(0);

        SegmentQuant quant = fixture.frame.getSegmentQuants().getSegQuants()[0];
        quant.setQindex(0);
        quant.setY2dc(0);
        quant.setY2ac_delta_q(0);
        quant.setY1dc(0);
        quant.setUvdc_delta_q(0);
        quant.setUvac_delta_q(0);

        mb.getY2SubBlock().getTokens()[0] = -8;

        mb.dequantMacroBlock(fixture.frame);

        for (int y = 0; y < 4; y++) {
