    // ------------------------------------------------------------------
    // Prediction context: off frame border samples (RFC 6386, 12.2)
    // ------------------------------------------------------------------

    @Test
    void getPredictReturnsOffFrameBorderSamples() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        // Default argument is the DC mode without a left neighbour
        assertFilled(127, subBlock.getPredict());

        // Modes that read the above row see 127 above the frame
        for (int mode : new int[]{
                Globals.B_DC_PRED, Globals.B_TM_PRED, Globals.B_VE_PRED, Globals.B_HE_PRED,
                Globals.B_LD_PRED, Globals.B_RD_PRED, Globals.B_VR_PRED, Globals.B_VL_PRED,
                Globals.B_HD_PRED, Globals.B_HU_PRED}) {
            assertFilled(127, subBlock.getPredict(mode, false));
        }
    }

    @Test
    void getPredictUsesLeftBorderSampleForModesThatReadTheLeftColumn() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        int[] leftModes = {
                Globals.B_TM_PRED, Globals.B_DC_PRED, Globals.B_VE_PRED, Globals.B_HE_PRED,
                Globals.B_VR_PRED, Globals.B_RD_PRED, Globals.B_HD_PRED
        };
        for (int mode : leftModes) {
            assertFilled(129, subBlock.getPredict(mode, true));
        }

        // These modes do not use the left column, so the border sample is 127
        for (int mode : new int[]{Globals.B_LD_PRED, Globals.B_VL_PRED, Globals.B_HU_PRED}) {
            assertFilled(127, subBlock.getPredict(mode, true));
        }
    }

    @Test
    void getPredictPrefersKnownBlocksOverBorderSamples() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        int[][] predict = filled(50);
        subBlock.setPredict(predict);

        assertSame(predict, subBlock.getPredict(), "stored prediction");
        assertSame(predict, subBlock.getPredict(Globals.B_HU_PRED, true), "stored prediction wins");

        int[][] dest = filled(200);
        subBlock.setDest(dest);

        // The neighbour lookups prefer the reconstructed block ...
        assertSame(dest, subBlock.getPredict(Globals.B_HE_PRED, true), "reconstructed block wins");
        // ... while the parameterless lookup keeps returning the stored prediction
        assertSame(predict, subBlock.getPredict(), "parameterless lookup returns the stored prediction");
    }

    @Test
    void getMacroBlockPredictUsesLeftBorderForHorizontalMode() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

