        for (int mode : new int[]{
                Globals.DC_PRED, Globals.V_PRED, Globals.TM_PRED, Globals.B_PRED}) {
            assertFilled(127, subBlock.getMacroBlockPredict(mode));
        }

        int[][] dest = filled(77);
        subBlock.setDest(dest);
        assertSame(dest, subBlock.getMacroBlockPredict(Globals.H_PRED), "known block wins");
    }

    @Test
    void reconBorderSamplesAre127AboveAnd129LeftOfTheFrame() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        assertFilled(127, subBlock.getReconAbove());
        assertFilled(129, subBlock.getReconLeft());

        // Above-left reads as 127 when the above macro block row is outside the
        // frame, and as 129 otherwise
        assertFilled(127, subBlock.getReconAboveLeft(false));
        assertFilled(129, subBlock.getReconAboveLeft(true));

        assertFilled(129, subBlock.getMacroBlockReconPredict(Globals.H_PRED));
        assertFilled(127, subBlock.getMacroBlockReconPredict(Globals.DC_PRED));
