        subBlock.setPredict(predict);
        assertSame(predict, subBlock.getReconPredict(Globals.B_DC_PRED, true),
                "prediction is used while the block is not reconstructed");

        int[][] dest = uniqueBlock();
        subBlock.setDest(dest);
        assertArrayEquals(uniqueBlock(), subBlock.getReconPredict(Globals.B_DC_PRED, true),
