    // ------------------------------------------------------------------
    // Reconstruction
    // ------------------------------------------------------------------

    @Test
    void reconstructAddsPredictionAndClampsToPixelRange() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);
        int[][] diff = new int[4][4];
        diff[0][0] = -200;   // -200 + 127 -> clamped to 0
        diff[1][1] = 200;    //  200 + 127 -> clamped to 255
        diff[2][2] = 10;     //   10 + 127 -> 137
        diff[3][3] = -127;   // -127 + 127 -> 0
        subBlock.setDiff(diff);

        subBlock.reconstruct();

        int[][] expected = filled(127);
        expected[0][0] = 0;
        expected[1][1] = 255;
        expected[2][2] = 137;
        expected[3][3] = 0;

        assertArrayEquals(expected, subBlock.getDest(), "reconstructed samples");
        assertArrayEquals(expected, subBlock.getRecon(), "unfiltered snapshot");
    }

    @Test
    void reconstructUsesStoredPredictionBlock() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);
        subBlock.setPredict(filled(100));
        int[][] diff = filled(5);
        diff[0][0] = 300;    // 300 + 100 -> 255
        diff[1][1] = -300;   // -300 + 100 -> 0
        subBlock.setDiff(diff);

        subBlock.reconstruct();

        int[][] expected = filled(105);
        expected[0][0] = 255;
        expected[1][1] = 0;
        assertArrayEquals(expected, subBlock.getDest());
    }

    @Test
    void reconstructDiscardsIntermediateStateForNonDebugMacroBlocks() throws Exception {
        SubBlock subBlock = new SubBlock(new MacroBlock(1, 1, false), null, null, SubBlock.Plane.Y1);
        subBlock.setDiff(uniqueBlock());
        subBlock.setPredict(filled(1));

        subBlock.reconstruct();

        assertTrue(subBlock.isDest(), "destination kept");
        assertTrue(subBlock.hasRecon(), "reconstruction kept");
        assertNull(subBlock.getDiff(), "residual released");
        assertNull(subBlock.getTokens(), "tokens released");
        assertFalse(hasStoredPrediction(subBlock), "prediction released");
    }

    @Test
    void reconstructRetainsIntermediateStateForDebugMacroBlocks() throws Exception {
        SubBlock subBlock = new SubBlock(new MacroBlock(1, 1, true), null, null, SubBlock.Plane.Y1);
        int[][] diff = filled(2);
        subBlock.setDiff(diff);
        int[][] predict = filled(3);
        subBlock.setPredict(predict);

        subBlock.reconstruct();

        assertSame(diff, subBlock.getDiff(), "residual retained");
        assertTrue(hasStoredPrediction(subBlock), "prediction retained");
        assertSame(predict, storedPrediction(subBlock), "prediction retained");
        assertNotNull(subBlock.getTokens(), "tokens retained");
        assertArrayEquals(filled(5), subBlock.getDest());
    }

    // ------------------------------------------------------------------
    // Dequantization
    // ------------------------------------------------------------------

    @Test
    void dequantSubBlockWithZeroCoefficientsProducesZeroResidual() throws Exception {
        VP8Frame frame = frameWithQuants(quants(10, 0, 0, 0));
        SubBlock subBlock = newSubBlock(new MacroBlock(1, 1, false), SubBlock.Plane.Y1);

        subBlock.dequantSubBlock(frame, null);

        int[][] diff = subBlock.getDiff();
        assertNotNull(diff, "residual computed");
        assertEquals(4, diff.length);
        assertEquals(4, diff[0].length);
        assertFilled(0, diff);
    }

    @Test
    void dequantSubBlockScalesDcCoefficientWithLumaQuantizer() throws Exception {
        // q index 10 yields a luma DC quantizer of 13, so a DC token of 1
        // reconstructs to (13 + 4) >> 3 == 2 for every sample
        VP8Frame frame = frameWithQuants(quants(10, 0, 6, 3));
        SubBlock subBlock = newSubBlock(new MacroBlock(1, 1, false), SubBlock.Plane.Y1);
        subBlock.getTokens()[0] = 1;

        subBlock.dequantSubBlock(frame, null);

        assertFilled(2, subBlock.getDiff());
    }

    @Test
    void dequantSubBlockAcCoefficientsSpreadOverTheWholeBlock() throws Exception {
        VP8Frame frame = frameWithQuants(quants(10, 0, 6, 3));
        SubBlock subBlock = newSubBlock(new MacroBlock(1, 1, false), SubBlock.Plane.Y1);
        subBlock.getTokens()[0] = 1;
        subBlock.getTokens()[5] = 2;

        subBlock.dequantSubBlock(frame, null);

        int[][] diff = subBlock.getDiff();
        assertNotFilled(2, diff);
        int[][] expected = {
                {8, 4, -1, -4},
                {4, 3, 1, -1},
                {-1, 1, 3, 4},
                {-4, -1, 4, 8},
        };
        assertArrayEquals(expected, diff, "inverse transform of the dequantized coefficients");
    }

    @Test
    void dequantSubBlockHonoursExplicitDcOverride() throws Exception {
        VP8Frame frame = frameWithQuants(quants(10, 0, 6, 3));

        int[] dcValues = {8, 39, 0, -16};
        int[] expected = {1, 5, 0, -2};
        for (int i = 0; i < dcValues.length; i++) {
            SubBlock subBlock = newSubBlock(new MacroBlock(1, 1, false), SubBlock.Plane.Y1);
            subBlock.getTokens()[0] = 5; // must be overridden

            subBlock.dequantSubBlock(frame, dcValues[i]);

            assertFilled(expected[i], subBlock.getDiff());
        }
    }

    @Test
    void dequantSubBlockUsesChromaQuantizersForUvPlanes() throws Exception {
        // Chroma DC quantizer is 18, luma DC quantizer is 13
        VP8Frame frame = frameWithQuants(quants(10, 0, 6, 3));
        MacroBlock macroBlock = new MacroBlock(1, 1, false);

        SubBlock u = newSubBlock(macroBlock, SubBlock.Plane.U);
        u.getTokens()[0] = 1;
        u.getTokens()[5] = 2;
        u.dequantSubBlock(frame, null);

        SubBlock v = newSubBlock(macroBlock, SubBlock.Plane.V);
        v.getTokens()[0] = 1;
        v.getTokens()[5] = 2;
        v.dequantSubBlock(frame, null);

        int[][] expectedUv = {
                {9, 5, -1, -5},
                {5, 3, 1, -1},
                {-1, 1, 4, 5},
                {-5, -1, 5, 10},
        };
        assertArrayEquals(expectedUv, u.getDiff(), "U plane residual");
        assertArrayEquals(u.getDiff(), v.getDiff(), "U and V share the chroma quantizers");

        SubBlock y = newSubBlock(macroBlock, SubBlock.Plane.Y1);
        y.getTokens()[0] = 1;
        y.getTokens()[5] = 2;
        y.dequantSubBlock(frame, null);

        assertFalse(Arrays.deepEquals(expectedUv, y.getDiff()),
                "luma must not be dequantized with the chroma quantizers");
    }

    @Test
    void dequantSubBlockUsesLumaQuantizersForY2Plane() throws Exception {
        VP8Frame frame = frameWithQuants(quants(10, 0, 6, 3));
        MacroBlock macroBlock = new MacroBlock(1, 1, false);

        SubBlock y1 = newSubBlock(macroBlock, SubBlock.Plane.Y1);
        y1.getTokens()[0] = 1;
        y1.dequantSubBlock(frame, null);

        SubBlock y2 = newSubBlock(macroBlock, SubBlock.Plane.Y2);
        y2.getTokens()[0] = 1;
        y2.dequantSubBlock(frame, null);

        assertArrayEquals(y1.getDiff(), y2.getDiff(), "Y2 uses the luma quantizers");
        assertFilled(2, y2.getDiff());
    }

    @Test
    void dequantSubBlockSelectsQuantizerOfMacroBlockSegment() throws Exception {
        VP8Frame frame = frameWithQuants(quantsPerSegment(10, 20, 30, 40));
        int[] expected = {2, 3, 3, 5};

        for (int segment = 0; segment < 4; segment++) {
            MacroBlock macroBlock = new MacroBlock(1, 1, false);
            macroBlock.setSegmentId(segment);
            SubBlock subBlock = newSubBlock(macroBlock, SubBlock.Plane.Y1);
            subBlock.getTokens()[0] = 1;

            subBlock.dequantSubBlock(frame, null);

            assertFilled(expected[segment], subBlock.getDiff());
        }
    }

    // ------------------------------------------------------------------
    // Token decoding
    // ------------------------------------------------------------------

    @Test
    void decodeSubBlockStopsImmediatelyAtEndOfBlock() throws IOException {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        subBlock.decodeSubBlock(decoder(0x00, 64), uniformCoefProbs(255), 0,
                SubBlock.planeToType(SubBlock.Plane.Y1, false), false);

        assertArrayEquals(ZERO_TOKENS, subBlock.getTokens(), "no coefficients decoded");
        assertFalse(subBlock.hasNoZeroToken(), "block has no non zero coefficient");
    }

    @Test
    void decodeSubBlockDecodesAllSixteenCoefficients() throws IOException {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        subBlock.decodeSubBlock(decoder(0xFF, 512), uniformCoefProbs(255), 0,
                SubBlock.planeToType(SubBlock.Plane.Y1, false), false);

        for (int i = 0; i < 16; i++) {
            assertEquals(ALL_ONES_TOKEN, subBlock.getTokens()[i], "token at position " + i);
        }
        assertTrue(subBlock.hasNoZeroToken(), "block has non zero coefficients");
    }

    @Test
    void decodeSubBlockSkipsDcPositionWhenY2BlockIsPresent() throws IOException {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        subBlock.decodeSubBlock(decoder(0xFF, 512), uniformCoefProbs(255), 0,
                SubBlock.planeToType(SubBlock.Plane.Y1, true), true);

        // With a Y2 block, the DC coefficient is coded in the Y2 block instead
        assertEquals(0, subBlock.getTokens()[0], "DC position must stay untouched");
        for (int i = 1; i < 16; i++) {
            assertEquals(ALL_ONES_TOKEN, subBlock.getTokens()[i], "token at position " + i);
        }
        assertTrue(subBlock.hasNoZeroToken());
    }

    @Test
    void decodeSubBlockReadsProbabilitiesForRequestedTypeAndContext() throws IOException {
        // 0x02 followed by zeros produces the decision sequence 1, 1, 0 for
        // tiny probabilities, which is the code for a positive coefficient of 1
        int[] stream = {0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
        int[][][][] probs = uniformCoefProbs(255);
        probs[0][0][0][0] = 0;
        probs[0][0][0][1] = 0;
        probs[0][0][0][2] = 0;

        SubBlock matching = newSubBlock(SubBlock.Plane.Y1);
        matching.decodeSubBlock(decoder(stream), probs, 0, 0, false);
        assertEquals(1, matching.getTokens()[0], "coefficient decoded from type 0 / context 0");
        assertTrue(matching.hasNoZeroToken());

        // Same stream, but a probability table without the permissive entries
        SubBlock otherType = newSubBlock(SubBlock.Plane.Y1);
        otherType.decodeSubBlock(decoder(stream), probs, 0, 1, false);
        assertArrayEquals(ZERO_TOKENS, otherType.getTokens(), "type 1 uses different probabilities");

        SubBlock otherContext = newSubBlock(SubBlock.Plane.Y1);
        otherContext.decodeSubBlock(decoder(stream), probs, 1, 0, false);
        assertArrayEquals(ZERO_TOKENS, otherContext.getTokens(), "context 1 uses different probabilities");
    }

    @Test
    void decodeSubBlockSelectsProbabilityBandPerCoefficientPosition() throws IOException {
        // The permissive probabilities are only configured for band 0, which is
        // used for the first coefficient of a block without a Y2 block
        int[] stream = {0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
        int[][][][] probs = uniformCoefProbs(255);
        probs[SubBlock.planeToType(SubBlock.Plane.Y1, false)][0][0][0] = 0;
        probs[SubBlock.planeToType(SubBlock.Plane.Y1, false)][0][0][1] = 0;
        probs[SubBlock.planeToType(SubBlock.Plane.Y1, false)][0][0][2] = 0;

        SubBlock noY2 = newSubBlock(SubBlock.Plane.Y1);
        noY2.decodeSubBlock(decoder(stream), probs, 0, SubBlock.planeToType(SubBlock.Plane.Y1, false), false);
        assertEquals(1, noY2.getTokens()[0], "first coefficient read from band 0");

        // When a Y2 block is present the first coefficient read is already in
        // band 1, which uses the strict probabilities, so the block ends at once
        SubBlock withY2 = newSubBlock(SubBlock.Plane.Y1);
        withY2.decodeSubBlock(decoder(stream), probs, 0, SubBlock.planeToType(SubBlock.Plane.Y1, true), true);
        assertArrayEquals(ZERO_TOKENS, withY2.getTokens(), "first coefficient read from band 1");
    }

    @Test
    void decodeSubBlockRecomputesHasNoZeroTokenFromCurrentCoefficients() throws IOException {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);
        subBlock.getTokens()[3] = 7;

        subBlock.decodeSubBlock(decoder(0x00, 64), uniformCoefProbs(255), 0,
                SubBlock.planeToType(SubBlock.Plane.Y1, false), false);

        assertEquals(7, subBlock.getTokens()[3], "pre-existing coefficient kept");
        assertTrue(subBlock.hasNoZeroToken(), "non zero coefficient detected");
    }

    // ------------------------------------------------------------------
    // Debug description
    // ------------------------------------------------------------------

    @Test
    void getDebugStringDescribesPlaneAndSubBlockMode() {
        MacroBlock macroBlock = new MacroBlock(1, 1, false);
        SubBlock y1 = newSubBlock(macroBlock, SubBlock.Plane.Y1);

        assertEquals("  Y1", y1.getDebugString(), "no sub block mode outside B_PRED macro blocks");

        assertEquals("  U", newSubBlock(macroBlock, SubBlock.Plane.U).getDebugString());
        assertEquals("  V", newSubBlock(macroBlock, SubBlock.Plane.V).getDebugString());
        assertEquals("  Y2", newSubBlock(macroBlock, SubBlock.Plane.Y2).getDebugString());
    }

    @Test
    void getDebugStringIncludesSubBlockModeForBPredMacroBlocks() {
        MacroBlock macroBlock = new MacroBlock(1, 1, false);
        macroBlock.setYMode(Globals.B_PRED);

        SubBlock y1 = macroBlock.getYSubBlock(0, 0);
        y1.setMode(Globals.B_DC_PRED);
        assertEquals("  Y1\n  B_DC_PRED", y1.getDebugString());

        y1.setMode(Globals.B_HU_PRED);
        assertEquals("  Y1\n  B_HU_PRED", y1.getDebugString());

        // Only luma sub blocks carry a sub block mode
        SubBlock y2 = macroBlock.getY2SubBlock();
        y2.setMode(Globals.B_DC_PRED);
        assertEquals("  Y2", y2.getDebugString());

        SubBlock chroma = macroBlock.getUSubBlock(0, 0);
        chroma.setMode(Globals.B_DC_PRED);
        assertEquals("  U", chroma.getDebugString());
    }
