    @Test
    void debugPaintingIsIgnoredWithoutDestination() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        subBlock.drawDebug();
        subBlock.drawDebugH();
        subBlock.drawDebugV();

        assertFalse(subBlock.isDest(), "debug painting must not allocate a destination");
        assertFilled(0, subBlock.getDest());
    }

    @Test
    void drawDebugHighlightsTopRowAndLeftColumn() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);
        subBlock.setDest(filled(10));

        subBlock.drawDebug();

        int[][] dest = subBlock.getDest();
        for (int i = 0; i < 4; i++) {
            assertEquals(128, dest[i][0], "first column, row " + i);
            assertEquals(128, dest[0][i], "first row, column " + i);
        }
        assertEquals(10, dest[1][1], "untouched interior sample");
        assertArrayEquals(filled(10), subBlock.getRecon(), "snapshot untouched by debug painting");
    }

    @Test
    void drawDebugHZeroesFirstColumnAndDrawDebugVZeroesFirstRow() {
        SubBlock horizontal = newSubBlock(SubBlock.Plane.Y1);
        horizontal.setDest(filled(10));
        horizontal.drawDebugH();

        for (int x = 0; x < 4; x++) {
            assertEquals(0, horizontal.getDest()[x][0], "column 0, row " + x);
        }
        assertEquals(10, horizontal.getDest()[0][1], "row 0 untouched by drawDebugH");

        SubBlock vertical = newSubBlock(SubBlock.Plane.Y1);
        vertical.setDest(filled(10));
        vertical.drawDebugV();

        for (int y = 0; y < 4; y++) {
            assertEquals(0, vertical.getDest()[0][y], "row 0, column " + y);
        }
        assertEquals(10, vertical.getDest()[1][0], "column 0 untouched by drawDebugV");
    }

    // ------------------------------------------------------------------
    // Prediction context: off frame border samples (RFC 6386, 12.2)
    // ------------------------------------------------------------------

    @Test
    void getPredictReturnsOffFrameBorderSamples() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        // Default argument is the DC mode without a left neighbour
        assertFilled(127, subBlock.getPredict());

        // Modes that read the above row see 127 above the frame
        for (int mode : new int[]{
                Globals.B_DC_PRED, Globals.B_TM_PRED, Globals.B_VE_PRED, Globals.B_HE_PRED,
                Globals.B_LD_PRED, Globals.B_RD_PRED, Globals.B_VR_PRED, Globals.B_VL_PRED,
                Globals.B_HD_PRED, Globals.B_HU_PRED}) {
            assertFilled(127, subBlock.getPredict(mode, false));
        }
    }

    @Test
    void getPredictUsesLeftBorderSampleForModesThatReadTheLeftColumn() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        int[] leftModes = {
                Globals.B_TM_PRED, Globals.B_DC_PRED, Globals.B_VE_PRED, Globals.B_HE_PRED,
                Globals.B_VR_PRED, Globals.B_RD_PRED, Globals.B_HD_PRED
        };
        for (int mode : leftModes) {
            assertFilled(129, subBlock.getPredict(mode, true));
        }

        // These modes do not use the left column, so the border sample is 127
        for (int mode : new int[]{Globals.B_LD_PRED, Globals.B_VL_PRED, Globals.B_HU_PRED}) {
            assertFilled(127, subBlock.getPredict(mode, true));
        }
    }

    @Test
    void getPredictPrefersKnownBlocksOverBorderSamples() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        int[][] predict = filled(50);
        subBlock.setPredict(predict);

        assertSame(predict, subBlock.getPredict(), "stored prediction");
        assertSame(predict, subBlock.getPredict(Globals.B_HU_PRED, true), "stored prediction wins");

        int[][] dest = filled(200);
        subBlock.setDest(dest);

        // The neighbour lookups prefer the reconstructed block ...
        assertSame(dest, subBlock.getPredict(Globals.B_HE_PRED, true), "reconstructed block wins");
        // ... while the parameterless lookup keeps returning the stored prediction
        assertSame(predict, subBlock.getPredict(), "parameterless lookup returns the stored prediction");
    }

    @Test
    void getMacroBlockPredictUsesLeftBorderForHorizontalMode() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        assertFilled(129, subBlock.getMacroBlockPredict(Globals.H_PRED));

        for (int mode : new int[]{
                Globals.DC_PRED, Globals.V_PRED, Globals.TM_PRED, Globals.B_PRED}) {
            assertFilled(127, subBlock.getMacroBlockPredict(mode));
        }

        int[][] dest = filled(77);
        subBlock.setDest(dest);
        assertSame(dest, subBlock.getMacroBlockPredict(Globals.H_PRED), "known block wins");
    }

    @Test
    void reconBorderSamplesAre127AboveAnd129LeftOfTheFrame() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        assertFilled(127, subBlock.getReconAbove());
        assertFilled(129, subBlock.getReconLeft());

        // Above-left reads as 127 when the above macro block row is outside the
        // frame, and as 129 otherwise
        assertFilled(127, subBlock.getReconAboveLeft(false));
        assertFilled(129, subBlock.getReconAboveLeft(true));

        assertFilled(129, subBlock.getMacroBlockReconPredict(Globals.H_PRED));
        assertFilled(127, subBlock.getMacroBlockReconPredict(Globals.DC_PRED));
    }

    @Test
    void getReconPredictUsesBorderSamplesForModesThatReadTheLeftColumn() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        int[] leftModes = {
                Globals.B_TM_PRED, Globals.B_DC_PRED, Globals.B_VE_PRED, Globals.B_HE_PRED,
                Globals.B_VR_PRED, Globals.B_RD_PRED, Globals.B_HD_PRED
        };
        for (int mode : leftModes) {
            assertFilled(129, subBlock.getReconPredict(mode, true), "mode " + mode);
            assertFilled(127, subBlock.getReconPredict(mode, false), "mode " + mode);
        }

        for (int mode : new int[]{Globals.B_LD_PRED, Globals.B_VL_PRED, Globals.B_HU_PRED}) {
            assertFilled(127, subBlock.getReconPredict(mode, true), "mode " + mode);
        }
    }

    @Test
    void getReconPredictPrefersReconstructionThenPrediction() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        int[][] predict = filled(33);
        subBlock.setPredict(predict);
        assertSame(predict, subBlock.getReconPredict(Globals.B_DC_PRED, true),
                "prediction is used while the block is not reconstructed");

        int[][] dest = uniqueBlock();
        subBlock.setDest(dest);
        assertArrayEquals(uniqueBlock(), subBlock.getReconPredict(Globals.B_DC_PRED, true),
                "unfiltered reconstruction wins over the prediction");
    }

    @Test
    void reconLookupsReturnTheUnfilteredReconstructionWhenAvailable() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y2);
        int[][] dest = uniqueBlock();
        subBlock.setDest(dest);

        assertArrayEquals(uniqueBlock(), subBlock.getReconAbove());
        assertArrayEquals(uniqueBlock(), subBlock.getReconLeft());
        assertArrayEquals(uniqueBlock(), subBlock.getReconAboveLeft(true));
        assertArrayEquals(uniqueBlock(), subBlock.getReconAboveLeft(false));
        assertArrayEquals(uniqueBlock(), subBlock.getMacroBlockReconPredict(Globals.H_PRED));
        assertArrayEquals(uniqueBlock(), subBlock.getReconPredict(Globals.B_VE_PRED, true));
    }

    // ------------------------------------------------------------------
    // Reconstruction
    // ------------------------------------------------------------------

    @Test
    void reconstructAddsPredictionAndClampsToPixelRange() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);
        int[][] diff = new int[4][4];
        diff[0][0] = -200;   // -200 + 127 -> clamped to 0
        diff[1][1] = 200;    //  200 + 127 -> clamped to 255
        diff[2][2] = 10;     //   10 + 127 -> 137
        diff[3][3] = -127;   // -127 + 127 -> 0
        subBlock.setDiff(diff);

        subBlock.reconstruct();

        int[][] expected = filled(127);
        expected[0][0] = 0;
        expected[1][1] = 255;
        expected[2][2] = 137;
        expected[3][3] = 0;

        assertArrayEquals(expected, subBlock.getDest(), "reconstructed samples");
        assertArrayEquals(expected, subBlock.getRecon(), "unfiltered snapshot");
    }

    @Test
    void reconstructUsesStoredPredictionBlock() {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);
        subBlock.setPredict(filled(100));
        int[][] diff = filled(5);
        diff[0][0] = 300;    // 300 + 100 -> 255
        diff[1][1] = -300;   // -300 + 100 -> 0
        subBlock.setDiff(diff);

        subBlock.reconstruct();

        int[][] expected = filled(105);
        expected[0][0] = 255;
        expected[1][1] = 0;
        assertArrayEquals(expected, subBlock.getDest());
    }

    @Test
    void reconstructDiscardsIntermediateStateForNonDebugMacroBlocks() throws Exception {
        SubBlock subBlock = new SubBlock(new MacroBlock(1, 1, false), null, null, SubBlock.Plane.Y1);
        subBlock.setDiff(uniqueBlock());
        subBlock.setPredict(filled(1));

        subBlock.reconstruct();

        assertTrue(subBlock.isDest(), "destination kept");
        assertTrue(subBlock.hasRecon(), "reconstruction kept");
        assertNull(subBlock.getDiff(), "residual released");
        assertNull(subBlock.getTokens(), "tokens released");
        assertFalse(hasStoredPrediction(subBlock), "prediction released");
    }

    @Test
    void reconstructRetainsIntermediateStateForDebugMacroBlocks() throws Exception {
        SubBlock subBlock = new SubBlock(new MacroBlock(1, 1, true), null, null, SubBlock.Plane.Y1);
        int[][] diff = filled(2);
        subBlock.setDiff(diff);
        int[][] predict = filled(3);
        subBlock.setPredict(predict);

        subBlock.reconstruct();

        assertSame(diff, subBlock.getDiff(), "residual retained");
        assertTrue(hasStoredPrediction(subBlock), "prediction retained");
        assertSame(predict, storedPrediction(subBlock), "prediction retained");
        assertNotNull(subBlock.getTokens(), "tokens retained");
        assertArrayEquals(filled(5), subBlock.getDest());
    }

