    // Dequantization
    // ------------------------------------------------------------------

    @Test
    void dequantSubBlockWithZeroCoefficientsProducesZeroResidual() throws Exception {
        VP8Frame frame = frameWithQuants(quants(10, 0, 0, 0));
        SubBlock subBlock = newSubBlock(new MacroBlock(1, 1, false), SubBlock.Plane.Y1);

        subBlock.dequantSubBlock(frame, null);

        int[][] diff = subBlock.getDiff();
        assertNotNull(diff, "residual computed");
        assertEquals(4, diff.length);
        assertEquals(4, diff[0].length);
        assertFilled(0, diff);
    }

    @Test
    void dequantSubBlockScalesDcCoefficientWithLumaQuantizer() throws Exception {
        // q index 10 yields a luma DC quantizer of 13, so a DC token of 1
        // reconstructs to (13 + 4) >> 3 == 2 for every sample
        VP8Frame frame = frameWithQuants(quants(10, 0, 6, 3));
        SubBlock subBlock = newSubBlock(new MacroBlock(1, 1, false), SubBlock.Plane.Y1);
        subBlock.getTokens()[0] = 1;

        subBlock.dequantSubBlock(frame, null);

        assertFilled(2, subBlock.getDiff());
    }

    @Test
    void dequantSubBlockAcCoefficientsSpreadOverTheWholeBlock() throws Exception {
        VP8Frame frame = frameWithQuants(quants(10, 0, 6, 3));
        SubBlock subBlock = newSubBlock(new MacroBlock(1, 1, false), SubBlock.Plane.Y1);
        subBlock.getTokens()[0] = 1;
        subBlock.getTokens()[5] = 2;

        subBlock.dequantSubBlock(frame, null);

        int[][] diff = subBlock.getDiff();
        assertNotFilled(2, diff);
        int[][] expected = {
                {8, 4, -1, -4},
                {4, 3, 1, -1},
                {-1, 1, 3, 4},
                {-4, -1, 4, 8},
        };
        assertArrayEquals(expected, diff, "inverse transform of the dequantized coefficients");
    }

    @Test
    void dequantSubBlockHonoursExplicitDcOverride() throws Exception {
        VP8Frame frame = frameWithQuants(quants(10, 0, 6, 3));

        int[] dcValues = {8, 39, 0, -16};
        int[] expected = {1, 5, 0, -2};
        for (int i = 0; i < dcValues.length; i++) {
            SubBlock subBlock = newSubBlock(new MacroBlock(1, 1, false), SubBlock.Plane.Y1);
            subBlock.getTokens()[0] = 5; // must be overridden

            subBlock.dequantSubBlock(frame, dcValues[i]);

            assertFilled(expected[i], subBlock.getDiff());
        }
    }

    @Test
    void dequantSubBlockUsesChromaQuantizersForUvPlanes() throws Exception {
        // Chroma DC quantizer is 18, luma DC quantizer is 13
        VP8Frame frame = frameWithQuants(quants(10, 0, 6, 3));
        MacroBlock macroBlock = new MacroBlock(1, 1, false);

        SubBlock u = newSubBlock(macroBlock, SubBlock.Plane.U);
        u.getTokens()[0] = 1;
        u.getTokens()[5] = 2;
        u.dequantSubBlock(frame, null);

        SubBlock v = newSubBlock(macroBlock, SubBlock.Plane.V);
        v.getTokens()[0] = 1;
        v.getTokens()[5] = 2;
        v.dequantSubBlock(frame, null);

        int[][] expectedUv = {
                {9, 5, -1, -5},
                {5, 3, 1, -1},
                {-1, 1, 4, 5},
                {-5, -1, 5, 10},
        };
        assertArrayEquals(expectedUv, u.getDiff(), "U plane residual");
        assertArrayEquals(u.getDiff(), v.getDiff(), "U and V share the chroma quantizers");

        SubBlock y = newSubBlock(macroBlock, SubBlock.Plane.Y1);
        y.getTokens()[0] = 1;
        y.getTokens()[5] = 2;
        y.dequantSubBlock(frame, null);

        assertFalse(Arrays.deepEquals(expectedUv, y.getDiff()),
                "luma must not be dequantized with the chroma quantizers");
    }

    @Test
    void dequantSubBlockUsesLumaQuantizersForY2Plane() throws Exception {
        VP8Frame frame = frameWithQuants(quants(10, 0, 6, 3));
        MacroBlock macroBlock = new MacroBlock(1, 1, false);

        SubBlock y1 = newSubBlock(macroBlock, SubBlock.Plane.Y1);
        y1.getTokens()[0] = 1;
        y1.dequantSubBlock(frame, null);

        SubBlock y2 = newSubBlock(macroBlock, SubBlock.Plane.Y2);
        y2.getTokens()[0] = 1;
        y2.dequantSubBlock(frame, null);

        assertArrayEquals(y1.getDiff(), y2.getDiff(), "Y2 uses the luma quantizers");
        assertFilled(2, y2.getDiff());
    }

    @Test
    void dequantSubBlockSelectsQuantizerOfMacroBlockSegment() throws Exception {
        VP8Frame frame = frameWithQuants(quantsPerSegment(10, 20, 30, 40));
        int[] expected = {2, 3, 3, 5};

        for (int segment = 0; segment < 4; segment++) {
            MacroBlock macroBlock = new MacroBlock(1, 1, false);
            macroBlock.setSegmentId(segment);
            SubBlock subBlock = newSubBlock(macroBlock, SubBlock.Plane.Y1);
            subBlock.getTokens()[0] = 1;

            subBlock.dequantSubBlock(frame, null);

            assertFilled(expected[segment], subBlock.getDiff());
        }
    }

