    @Test
    void decodeSubBlockStopsImmediatelyAtEndOfBlock() throws IOException {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        subBlock.decodeSubBlock(decoder(0x00, 64), uniformCoefProbs(255), 0,
                SubBlock.planeToType(SubBlock.Plane.Y1, false), false);

        assertArrayEquals(ZERO_TOKENS, subBlock.getTokens(), "no coefficients decoded");
        assertFalse(subBlock.hasNoZeroToken(), "block has no non zero coefficient");
    }

    @Test
    void decodeSubBlockDecodesAllSixteenCoefficients() throws IOException {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        subBlock.decodeSubBlock(decoder(0xFF, 512), uniformCoefProbs(255), 0,
                SubBlock.planeToType(SubBlock.Plane.Y1, false), false);

        for (int i = 0; i < 16; i++) {
            assertEquals(ALL_ONES_TOKEN, subBlock.getTokens()[i], "token at position " + i);
        }
        assertTrue(subBlock.hasNoZeroToken(), "block has non zero coefficients");
    }

    @Test
    void decodeSubBlockSkipsDcPositionWhenY2BlockIsPresent() throws IOException {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);

        subBlock.decodeSubBlock(decoder(0xFF, 512), uniformCoefProbs(255), 0,
                SubBlock.planeToType(SubBlock.Plane.Y1, true), true);

        // With a Y2 block, the DC coefficient is coded in the Y2 block instead
        assertEquals(0, subBlock.getTokens()[0], "DC position must stay untouched");
        for (int i = 1; i < 16; i++) {
            assertEquals(ALL_ONES_TOKEN, subBlock.getTokens()[i], "token at position " + i);
        }
        assertTrue(subBlock.hasNoZeroToken());
    }

    @Test
