        // 0x02 followed by zeros produces the decision sequence 1, 1, 0 for
        // tiny probabilities, which is the code for a positive coefficient of 1
        int[] stream = {0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
        int[][][][] probs = uniformCoefProbs(255);
        probs[0][0][0][0] = 0;
        probs[0][0][0][1] = 0;
        probs[0][0][0][2] = 0;

        SubBlock matching = newSubBlock(SubBlock.Plane.Y1);
        matching.decodeSubBlock(decoder(stream), probs, 0, 0, false);
        assertEquals(1, matching.getTokens()[0], "coefficient decoded from type 0 / context 0");
        assertTrue(matching.hasNoZeroToken());

        // Same stream, but a probability table without the permissive entries
        SubBlock otherType = newSubBlock(SubBlock.Plane.Y1);
        otherType.decodeSubBlock(decoder(stream), probs, 0, 1, false);
        assertArrayEquals(ZERO_TOKENS, otherType.getTokens(), "type 1 uses different probabilities");

        SubBlock otherContext = newSubBlock(SubBlock.Plane.Y1);
        otherContext.decodeSubBlock(decoder(stream), probs, 1, 0, false);
        assertArrayEquals(ZERO_TOKENS, otherContext.getTokens(), "context 1 uses different probabilities");
    }

    @Test
    void decodeSubBlockSelectsProbabilityBandPerCoefficientPosition() throws IOException {
        // The permissive probabilities are only configured for band 0, which is
        // used for the first coefficient of a block without a Y2 block
        int[] stream = {0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
        int[][][][] probs = uniformCoefProbs(255);
        probs[SubBlock.planeToType(SubBlock.Plane.Y1, false)][0][0][0] = 0;
        probs[SubBlock.planeToType(SubBlock.Plane.Y1, false)][0][0][1] = 0;
        probs[SubBlock.planeToType(SubBlock.Plane.Y1, false)][0][0][2] = 0;

        SubBlock noY2 = newSubBlock(SubBlock.Plane.Y1);
        noY2.decodeSubBlock(decoder(stream), probs, 0, SubBlock.planeToType(SubBlock.Plane.Y1, false), false);
        assertEquals(1, noY2.getTokens()[0], "first coefficient read from band 0");

        // When a Y2 block is present the first coefficient read is already in
        // band 1, which uses the strict probabilities, so the block ends at once
        SubBlock withY2 = newSubBlock(SubBlock.Plane.Y1);
        withY2.decodeSubBlock(decoder(stream), probs, 0, SubBlock.planeToType(SubBlock.Plane.Y1, true), true);
        assertArrayEquals(ZERO_TOKENS, withY2.getTokens(), "first coefficient read from band 1");
    }

    @Test
    void decodeSubBlockRecomputesHasNoZeroTokenFromCurrentCoefficients() throws IOException {
        SubBlock subBlock = newSubBlock(SubBlock.Plane.Y1);
        subBlock.getTokens()[3] = 7;

        subBlock.decodeSubBlock(decoder(0x00, 64), uniformCoefProbs(255), 0,
                SubBlock.planeToType(SubBlock.Plane.Y1, false), false);

        assertEquals(7, subBlock.getTokens()[3], "pre-existing coefficient kept");
        assertTrue(subBlock.hasNoZeroToken(), "non zero coefficient detected");
    }

    // ------------------------------------------------------------------
    // Debug description
    // ------------------------------------------------------------------

    @Test
    void getDebugStringDescribesPlaneAndSubBlockMode() {
        MacroBlock macroBlock = new MacroBlock(1, 1, false);
        SubBlock y1 = newSubBlock(macroBlock, SubBlock.Plane.Y1);

        assertEquals("  Y1", y1.getDebugString(), "no sub block mode outside B_PRED macro blocks");

        assertEquals("  U", newSubBlock(macroBlock, SubBlock.Plane.U).getDebugString());
        assertEquals("  V", newSubBlock(macroBlock, SubBlock.Plane.V).getDebugString());
        assertEquals("  Y2", newSubBlock(macroBlock, SubBlock.Plane.Y2).getDebugString());
    }

    @Test
    void getDebugStringIncludesSubBlockModeForBPredMacroBlocks() {
        MacroBlock macroBlock = new MacroBlock(1, 1, false);
        macroBlock.setYMode(Globals.B_PRED);

        SubBlock y1 = macroBlock.getYSubBlock(0, 0);
        y1.setMode(Globals.B_DC_PRED);
        assertEquals("  Y1\n  B_DC_PRED", y1.getDebugString());

        y1.setMode(Globals.B_HU_PRED);
        assertEquals("  Y1\n  B_HU_PRED", y1.getDebugString());

        // Only luma sub blocks carry a sub block mode
        SubBlock y2 = macroBlock.getY2SubBlock();
        y2.setMode(Globals.B_DC_PRED);
        assertEquals("  Y2", y2.getDebugString());

        SubBlock chroma = macroBlock.getUSubBlock(0, 0);
        chroma.setMode(Globals.B_DC_PRED);
        assertEquals("  U", chroma.getDebugString());
    }
}

