        assertEquals(1, frame.getMacroBlockCols());
        assertEquals(1, frame.getMacroBlockRows());
        assertEquals(4, frame.getQIndex());
        assertEquals(0, frame.getSharpnessLevel());

        SegmentQuants quants = frame.getSegmentQuants();
        assertNotNull(quants);
        assertEquals(4, quants.getSegQuants().length);
        for (SegmentQuant quant : quants.getSegQuants()) {
            assertEquals(4, quant.getQindex());
            assertEquals(0, quant.getFilterStrength());
            assertEquals(8, quant.getY1dc());
            assertEquals(8, quant.getY1ac());
            assertEquals(16, quant.getY2dc());
            assertEquals(12, quant.getY2ac_delta_q());
            assertEquals(8, quant.getUvdc_delta_q());
            assertEquals(8, quant.getUvac_delta_q());
        }

        assertEquals(0x008800, result.image.getRGB(0, 0) & 0xFFFFFF);
        assertNotNull(frame.getTokenBoolDecoder());
        assertSame(frame.getTokenBoolDecoder(), frame.getTokenBoolDecoder());
    }

