    @Test
    void decodeReportsProgressAfterEveryMacroBlockRow() throws IOException {
        VP8Frame frame = frame("bug3.webp");
        RecordingProgressListener listener = new RecordingProgressListener();
        frame.setProgressListener(listener);
        BufferedImage destination = new BufferedImage(95, 95, BufferedImage.TYPE_3BYTE_BGR);

        assertTrue(frame.decode(destination.getRaster(), null));
        assertEquals(6, frame.getMacroBlockCols());
        assertEquals(6, frame.getMacroBlockRows());
        assertEquals(6, listener.progress.size());

        for (int i = 0; i < listener.progress.size(); i++) {
            assertEquals((i + 1) * 100.0f / 6.0f, listener.progress.get(i), FLOAT_DELTA);
        }
        assertEquals(100.0f, listener.progress.get(listener.progress.size() - 1), 0.0f);
    }

    @Test
