        DecodeResult full = decode("small_31x13.webp", 31, 13, null);
        Rectangle sourceRegion = new Rectangle(5, 3, 9, 7);
        ImageReadParam param = new ImageReadParam();
        param.setSourceRegion(sourceRegion);

        DecodeResult cropped = decode("small_31x13.webp", 9, 7, param);

        for (int y = 0; y < sourceRegion.height; y++) {
