    @Test
    void decodeHonorsSourceSubsamplingWithOddImageDimensions() throws IOException {
        DecodeResult full = decode("small_31x13.webp", 31, 13, null);

        ImageReadParam param = new ImageReadParam();
        param.setSourceRegion(new Rectangle(0, 0, 31, 13));
        param.setSourceSubsampling(2, 2, 0, 0);

        DecodeResult subsampled = decode("small_31x13.webp", 16, 7, param);

        for (int y = 0; y < subsampled.image.getHeight(); y++) {
            for (int x = 0; x < subsampled.image.getWidth(); x++) {
                assertEquals(full.image.getRGB(x * 2, y * 2), subsampled.image.getRGB(x, y),
                        "pixel (" + x + ", " + y + ") differs from sampled full-frame pixel");
            }
        }
    }

