    private static DecodeResult decode(String resource, int width, int height, ImageReadParam param) throws IOException {
        VP8Frame frame = frame(resource);
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_3BYTE_BGR);
        boolean decoded = frame.decode(image.getRaster(), param);
        return new DecodeResult(frame, image, decoded);
    }

    private static VP8Frame frame(String resource) throws IOException {
        return new VP8Frame(stream(vp8Chunk(readResource(resource))), false);
    }

    private static ImageInputStream stream(byte[] bytes) {
        return new MemoryCacheImageInputStream(new ByteArrayInputStream(bytes));
    }

    private static byte[] readResource(String resource) throws IOException {
        String path = RESOURCE_ROOT + resource;
        try (InputStream input = VP8FrameTests.class.getResourceAsStream(path)) {
            if (input == null) {
                throw new IOException("Missing test resource: " + path);
            }

            ByteArrayOutputStream output = new ByteArrayOutputStream();
            byte[] buffer = new byte[4096];
            int count;
            while ((count = input.read(buffer)) >= 0) {
                output.write(buffer, 0, count);
            }
            return output.toByteArray();
        }
    }

    private static byte[] vp8Chunk(byte[] webp) throws IOException {
        if (webp.length < 20
                || webp[0] != 'R' || webp[1] != 'I' || webp[2] != 'F' || webp[3] != 'F'
                || webp[8] != 'W' || webp[9] != 'E' || webp[10] != 'B' || webp[11] != 'P') {
            throw new IOException("Not a WebP RIFF container");
        }

        int offset = 12;
        while (offset + 8 <= webp.length) {
            int length = readLittleEndianInt(webp, offset + 4);
            if (length < 0 || offset + 8L + length > webp.length) {
                throw new IOException("Invalid WebP chunk length at offset " + offset);
            }

            if (webp[offset] == 'V' && webp[offset + 1] == 'P'
                    && webp[offset + 2] == '8' && webp[offset + 3] == ' ') {
                byte[] chunk = new byte[length];
                System.arraycopy(webp, offset + 8, chunk, 0, length);
                return chunk;
            }

            offset += 8 + length + (length & 1);
        }

        throw new IOException("WebP container has no VP8 chunk");
    }

    private static int readLittleEndianInt(byte[] data, int offset) {
        return (data[offset] & 0xFF)
                | (data[offset + 1] & 0xFF) << 8
                | (data[offset + 2] & 0xFF) << 16
                | (data[offset + 3] & 0xFF) << 24;
    }

    private static final class DecodeResult {
        final VP8Frame frame;
        final BufferedImage image;
        final boolean decoded;

        DecodeResult(VP8Frame frame, BufferedImage image, boolean decoded) {
            this.frame = frame;
            this.image = image;
            this.decoded = decoded;
        }
    }

    private static final class RecordingProgressListener implements IIOReadProgressListener {
        final List<Float> progress = new ArrayList<>();

        @Override
        public void sequenceStarted(javax.imageio.ImageReader source, int minIndex) {
        }

        @Override
        public void sequenceComplete(javax.imageio.ImageReader source) {
        }

        @Override
        public void imageStarted(javax.imageio.ImageReader source, int imageIndex) {
        }

        @Override
        public void imageProgress(javax.imageio.ImageReader source, float percentageDone) {
            progress.add(percentageDone);
        }

        @Override
        public void imageComplete(javax.imageio.ImageReader source) {
        }

        @Override
        public void thumbnailStarted(javax.imageio.ImageReader source, int imageIndex, int thumbnailIndex) {
        }

        @Override
        public void thumbnailProgress(javax.imageio.ImageReader source, float percentageDone) {
        }

        @Override
        public void thumbnailComplete(javax.imageio.ImageReader source) {
        }

        @Override
        public void readAborted(javax.imageio.ImageReader source) {
        }
    }
